INSERT INTO public.training_library (age_group, training_number, exercises)
VALUES
('O10', 1, '{"session_a": [{"type": "warming_up", "title": "GEWOON TIKKERTJE", "content": "Eén speler probeert als tikker de andere spelers te tikken.\nVariatie:\nIdem met een bal aan de voet.\nOpgelet!\nJe mag weer deelnemen als een \"vrije speler\" je weer \"vrij\" getikt heeft.\nMaterialen\nDuur spel:10-15 min\nDuur ronde: 1 a 2 min\nAantal: 6-8 of meer spelers\nPylonen: 4 om het speelveld af te bakenen."}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º (ZELFDE/ANDERE BEEN) IN STROOMVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nlinker/rechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Speler 3 speelt naar speler 4\n- idem als beschreven bij A.\nD. Speler 4 speelt naar speler 5\n- idem als beschreven bij B, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nMaterialen\nAantal spelers: 5-7\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "AANBIEDEN, TOT 45º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: 4-6\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "test", "title": "WENDBAARHEIDSTEST 1", "content": "Voor deze test wordt in het strafschopgebied, tussen de doellijn\nen de rand van het gebied, een parcours ( zie tekening) uitgezet.\nHet protocol voor deze test luidt als volgt:\nDe test start vanuit buikligging. Vervolgens wordt het hele traject\nin korte sprintjes, van pylon naar pylon, afgelegd.\nDe pylonen worden daarbij,tot het bereiken van de finish, telkens\nzo kort mogelijk gerond.\nMaterialen\nAantal spelers: alle spelers\nAantal pylonen:8\nAfstand tussen de pylonen:gebruik de\naangegeven lijnen en verdeel de tussenliggende\nruimte gelijkmatig\nSchrijfbenodigdheden\nAanwijzingen\n- ontwikkel, zowel heen als terug, een zo\nhoog mogelijke snelheid\n- draai kort om de pylon\n- neem minimaal 2-3 minuten rust tussen\ntwee testen\nSPRINTTEST\nMethodiek\nVoor deze test wordt in de breedte van het strafschopgebied, op\neen onderlinge afstand van tekens 10 meter, met 5 pylonen een\nparcours uitgezet.\nDe spelers starten de sprint vanaf de zijkant van het “16-\nmetergebied” vanuit stilstand en sprinten vervolgens om de\neerste pylon heen weer terug, gevolgd door een sprint om de\ntweede pylon heen en weer terug. Idem om de derde en de vierde\npylon.\nDe behaalde eindtijd wordt gemeten en vastgelegd.\nMaterialen\nAantal spelers: alle spelers\nAantal pylonen: 5\nAfstand tussen de pylonen: 10 mtr.\n1 stopwatch\nSchrijfbenodigdheden.\n- deze test heeft tot doel om de “reactie/\nacceleratie- en/of de maximale snelheid” te\ntoetsen/meten.\nAanwijzingen\n- zowel heen als terug een zo hoog mogelijke\nsnelheid ontwikkelen\n- kort om de pylon draaien\n- neem minimaal 2-3 minuten rust tussen\ntwee testen."}, {"type": "techniek", "title": "AANVALLEN DOOR MIDDENVELDERS EN AANVALLERS (5 : 4+KEEPER) KLEIN VELD", "content": "D.w.z. dat 5 aanvallers/ middenvelders d.m.v. samenspel kansen\ncreëren.\nDe 4 verdedigers /middenvelders+ keeper kunnen scoren door de\nbal over de lijn van één van de kleine doetjes te dribbelen.\nDe aanvallers kunnen op het grote doel scoren.\nDe oefening start altijd bij de aanvallers.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nMiddenvelders/aanvallers bij aanvallen\ncoachen op:\n- het samenspelen vanuit een halve kom\n- het opkomen van de middenvelder\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (7+11)\n- het loskomen van de tegenstander d.m.v.\nvooracties.\n- het creëren van een twee tegen een situatie.\nMiddenvelders/aanvallers bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)\n- het direct druk zetten op de bal."}]}'::jsonb),
('O10', 2, '{"session_a": [{"type": "warming_up", "title": "A. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 4)\n- Akka (buiten-binnen) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 D: AANBIEDEN, TOT 135º (ZELFDE/ANDERE BEEN) IN RUITVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Speler 3 speelt naar speler 4\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, aannemen en spelen met het zelfde been.\nVariatie in aanbieden:\n- naar rechts\n- voorwaarts\n- achterwaarts\nVariatie\nVariatie 1: Aanbieden voorwaarts en achterwaarts\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "(4 : 2) OEFENING 1", "content": "Vier aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe aanvaller die een fout maakt wisselt van taak met de langst\nstaande verdediger.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 12m bij 10m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)\nLIJNDRIBBEL 1:1\nMethodiek\nEén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna de bal over de lijn aan de overkant van het\nvak te dribbelen.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren."}], "session_b": [{"type": "warming_up", "title": "UIT DE RUG", "content": "Oefeningen, waarbij de spelers voor elkaar staan. De voorste speler staat hierbij\nin een vak van 2 bij 3 meter.\nDe achterste speler probeert, door plotseling te versnellen, uit de rug van de\nvoorste speler te komen en zonder getikt te worden de finishlijn te behalen.\nOpgelet!\nHet is een reactiespel, waarbij de jongste jeugd spelenderwijs het spel wordt\naangeleerd.\nLater, bij de oudere jeugd, kan daar goed gebruik van worden gemaakt.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 6\nAantal ballen: 0\nOrganisatie:\nDe spelers staan voor elkaar. Bij deze oefening ligt het initiatief ligt bij de\nachterste speler."}, {"type": "techniek", "title": "B. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 4)\n- Sleep (Stap 3)\n- Akka (binnen-voor) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Aai buitenkant voet\n(Stap 4), Sleep (Stap 3) en Akka (binnen-voor) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VOOR JE: IN STROOMVORM", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\nDribbelen buitenkant voet:\n- Akka (buiten-binnen) (Stap 3A)\n- Schaar (Stap 5A)\nDribbelen buitenkant voet, inzet beweging binnenkant voet:\n- Aai buitenkant voet (Stap 5A)\n- Sleep (Stap 4A)\n- Akka (binnen-voor) (Stap 3A)\n- Uitstappen/meenemen (Stap 5A)\n- Akka (binnen-buiten) (Stap 3A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB. Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit.\nC. Daarna dribbelt hij, met de bal aan de voet, richting doel om\nvervolgens hierop af te ronden.\nD. Speler 1 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE -pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}]}'::jsonb),
('O10', 3, '{"session_a": [{"type": "warming_up", "title": "C. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Uitstappen meenemen (Stap 4)\n- Akka (binnen-buiten) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 C: INGOOIEN, AANBIEDEN, TOT 90º IN VIERKANTSVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 gooit de bal in\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 pakt de bal op.\nC. Spelers 3 speelt naar speler 4\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, met rechts aannemen en met links spelen.\n- idem, andersom met het andere been.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nIngooi:\n- beide voeten houden contact met de grond\n- de bal achter het hoofd loslaten\n- beide handen op de bal houden\n- voeten in de richting van het gooien\n- op het juiste been ingooien.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet.\nSTAP 2.1 A: KOPPEN (RECHT) VANUIT ZITTENDE POSITIE\nMethodiek\nOefening met 2-tallen, waarbij speler 1 recht t.o.v. speler 2 staat\nen speler 2 op de grond zit.\nA. Speler 1 speelt naar speler 2\n- speler 1 gooit de bal onderhands aan.\nB. Speler 2 speelt naar speler 1\n- speler 2 kopt de bal recht terug , etc.\nMaterialen\nAantal spelers: 2\nAantal ballen: per tweetal een bal\nOnderlinge afstand pylonen:\n1e jaars E-pupillen: 2 m\n2e jaars E-pupillen: 2 m\nDoordraaien:\n- wisselen van functie naar eigen inzicht.\nAanwijzingen\n- bovenlichaam naar achteren, kin op de\nborst\n- armen voor je houden\n- juiste moment bovenlichaam naar voren en\narmen naar achter\n- bal raken met het voorhoofd\n- speler 2 krijgt de bal recht aangegooid en\nwordt daardoor gedwongen om de bal ook\nrecht terug te koppen."}, {"type": "techniek", "title": "LIJNDRIBBEL 2:1 MET DOEL", "content": "d.w.z. dat 2 aanvallers d.m.v. samenspel/ een persoonlijke actie\neen verdediger uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 2 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdediger kan de afgepakte bal scoren door de bal over de\nlijn aan de overkant te dribbelen.\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen:\nF-pupillen: 15m bij 10m\nE-pupillen: 18m bij 12m\nD-pupillen: 20m bij 15m\nC-,B-,A-junioren: 25m bij 20m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- keuzes maken aan de bal( 1:1 of overspelen)\n- rekening houden, bij het innemen van een\naanvallende positie, met de omschakeling bij\nbalverlies(restverdediging)\nVerdediger coachen op:\n- rekening houden met een goed zicht op de\npositie van de beide aanvallers bij het\ninnemen van een verdedigende positie(open\nstaan)\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel."}], "session_b": [{"type": "test", "title": "SPEEDLADDER (1)", "content": "Is een oefening, waarbij de voorwaartse vormen worden\naangeleerd in de speedladder. De oefening is opgebouwd van\ngrove motoriek naar de fijne motoriek. Dat wil zeggen binnen de\nlooptraining, er wordt gewerkt van een skipping naar skipping 45\ngraden en vervolgens naar kort voetenwerk.\nStap 1: Eén voetje in het raam plaatsen.\nStap 2: Twee voetjes in het raam plaatsen.\nStap 3: Drie voetjes in het raam plaatsen.\nDifferentiatie:\nStroop de ladder op, zodat er door de spelers ten alle tijden een\nskipping ingezet moet worden.\nLet op!\nDeze vormen kunnen spelenderwijs worden aangeleerd.\nMaterialen\nAantal spelers: het gehele team.\nAantal speedladders:\nEén, bij voorkeur twee.\nAantal pylonnen:\nEén\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast.\nA. TEGENSTANDER NAAST JE: IN LIJNVORM\nMethodiek\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- De verandering (Stap 3)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "B. TEGENSTANDER NAAST JE: IN LIJNVORM HEEN TERUG", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt naar overstaande pylon.\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Kappen achter het standbeen (Stap 2)\n- Kappen binnenkant voet (Stap 3)\nC. Speler dribbelt terug en herhaald stap B bij de pylon.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n(4 : 2) OEFENING 1\nMethodiek\nVier aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe aanvaller die een fout maakt wisselt van taak met de langst\nstaande verdediger.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 12m bij 10m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 1:1", "content": "Eén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}]}'::jsonb),
('O10', 4, '{"session_a": [{"type": "warming_up", "title": "CLUBS / LANDENSPEL", "content": "Elke speler heeft een bal en dribbelt in het rond.\nIn de hoeken van het veld zijn vierkanten, die de namen dragen\nvan een voetbalclub of een land.\nBij het noemen van de naam van de club of het land moeten de\nspelers zo snel mogelijk naar het desbetreffende vak dribbelen en\ndaar met de voet op de bal blijven staan.\nDe laatst aangekomen speler krijgt een strafpunt.\nWinnaar is degene met de minste strafpunten.\nVariatie in aanbieden:\n- Met Kerst, Pasen of Sinterklaas gebruik je deze themagerichte\nnamen.\n- Spelers moeten de bal stoppen door b.v. op de bal te gaan zitten\nof iets anders te doen.\nMaterialen\nAantal spelers: 4-10\nAantal ballen: elke speler 1 bal\nAantal pylonen: 16\nVeldafmeting: 20 bij 20 meter (incl. hoekvakken\nvan 4 bij 4 meter)\nAanwijzingen\nSpelers coachen op:\n- De bal dichtbij je houden.\n- Probeer de bal zoveel mogelijk aan te raken.\n- Probeer bij iedere stap de bal een keer aan\nte raken.\n- Door het vele bal contact kunnen spelers\ngemakkelijker de bal sturen.\n- De bal moet onder de voet gestopt worden\nSTAP 2.2 A: HEEN/TERUG IN LIJN/STROOMVORM\nMethodiek\nA. Speler 1 speelt naar speler 2\n- speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 3\n- speler 2 kaatst de bal met de binnenkant van de rechtervoet.\nC. Speler 3 speelt naar speler 4\n- speler 3 kaatst de bal met de binnenkant van de rechtervoet, etc.\nVariatie in uitvoering:\n- idem met links uitvoeren.\nMaterialen\nAantal spelers: 3-4\nAantal pylonen: 2\nAantal ballen: 1\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- na de pass loopt de speler achter de bal aan\nnaar de volgende pylon\nA1. - speler 1 sluit achter in de rij van speler 2\naan\nB1. - speler 2 sluit achter in de rij van speler 1\naan, etc.\nAanwijzingen\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "IN STROOMVORM (2)", "content": "Deze oefenvorm wordt uitgevoerd met twee groepen binnen een\nafgebakend vak.\nA. Speler 1 passed de bal, schuin over de breedte, op de vragende\nspeler 2.\nB. Speler 2 krijgt de bal zodanig en met de juiste snelheid\naangespeeld, dat hij hem direct op het doel kan schieten.\nOpgelet!\nDe spelers moeten de bal in één keer schieten en vooral niet stil\ngaan staan om te schieten.\nVariatie in uitvoering:\n- Idem andersom met het andere been.\n- Vergroot/verklein de afstand ten opzichte van het schietpunt en/\nof het vak.\nMaterialen\nAantal spelers: 8- 12\nAantal ballen: 4-6\nAantal pylonen: 6\nBreedte speelveld: 20m\nDoelen: 2\nF-,E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen:\nStartafstand vanaf doel:\n2e jaars F-pupillen: 11 m\n1e jaars E-pupillen: 13 m\n2e jaars E-pupillen: 15 m\nD-pupillen: 17 m\nC-,B-,A-junioren: >19 m\nSchietafstand vanaf doel:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Nadat de speler geschoten heeft haalt hij zijn\neigen bal op en sluit achter in de andere rij aan.\n- Nadat een speler de beginpass heeft gegeven\nsluit hij aan in de rij aan de andere zijde van het\ndoel.\nAanwijzingen\nSpelers coachen op:\n- Juist inschatten van de snelheid van de bal\nom met je passen goed uit te komen, zodat\nje direct op doel kunt afwerken.\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Afhankelijk van de situatie met\nde binnenkant of met de volle wreef\n- Standbeen iets voorbij de bal dan blijft de\nbal laag.\n- Standbeen iets achter de bal en raak de bal\naan de onderkant, dan gaat de bal omhoog."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "KNIEHEF TIKKERTJE / HAKKEN-BIL TIKKERTJE", "content": "Dit is een oefening, waarbij de speler(s) de stap van één van de onderstaande\ntechnieken uitvoeren in de vorm van een tikspel. Eén speler moet, als tikker, de\nandere spelers proberen te tikken, terwijl zij (tikker en overige spelers) tijdens\nhet lopen één van de onderstaande technieken verwerken in hun looptechniek.\n1. Skipping (Stap 4)\n2. Hielaanslag (Stap 2)\nTerug komen tijdens het tikspel:\n- hierbij wordt gewerkt vanuit het principe “3 is te veel”.Dat wil zeggen dat\ntelkens als er een derde speler bij de 2 langs de kant staande afgetikte spelers\naansluit, de eerste afgetikte speler weer mee gaat doen aan het spel.\nDifferentiatie:\n- bij dit spel kan je het aantal tikkers variëren.\nOpgelet!\n- dit zijn introductievormen voor de looptraining.\nMaterialen\nAantal spelers: 15\nOrganisatie:\n- de afmeting van het vak is 10 bij 15 meter."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN EEN LIJNVORM", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de voet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan (deze doet alsof hij een speler in de rug heeft).\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Binnen-buitenkant wegdraai (Stap 4)\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\nC. Speler 1 dribbelt naar speler 6\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 6.\nIdem voor de spelers 4,5 en 6 in tegengestelde richting, etc.\nVariatie:\nIdem, maar nu met het andere been uitvoeren.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 6\nAantal ballen; 2\nAantal pylonen: 3\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt, na de pass op speler 2, diens\nplaats in. Speler 2 dribbelt naar speler 6 en geeft\nhem de bal. Speler 4 neemt, na de pass op\nspeler 5, diens plaats in en speler 5 geeft de bal\naan speler 3, etc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN LIJNVORM HEEN TERUG", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt naar overstaande pylon.\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Kappen buitenkant voet (Stap 3)\n- Binnen-buitenkant wegdraai (Stap 3)\n- De Overstap (Stap 4)\nC. Speler dribbelt terug en herhaald stap B bij de pylon.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken De Overstap (Stap 4),\nKappen buitenkant voet (Stap 3) en Binnen buiten wegdraai (Stap\n3+4).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nOPBOUW DOOR VERDEDIGERS EN MIDDENVELDER (5+KEEPER : 4) KLEIN VELD\nMethodiek\nD.w.z. dat 5 verdedigers / middenvelders + keeper d.m.v.\nsamenspel 4 aanvallers/ middenvelders uitspelen, om daarna te\nscoren door de bal over de lijn van een van de doeltjes te\ndribbelen.\nDe aanvallers kunnen de afgepakte bal scoren op het grote doel.\nDe opbouw start altijd bij de doelman.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nSpelers te kort! Zorg dan dat je opbouwende\npartij een speler meer heeft.\nAanwijzingen\nVerdedigers/middenvelders bij opbouw\ncoachen op:\n- het breed maken van het veld door de\nverdedigers. Wordt één van de verdedigers\nin gespeeld dan knijpt de ander naar binnen\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (2+5)\n- het diep weglopen, om ruimte te maken,\nvan de centrale middenvelder\n- het benutten van een overtalsituatie\nVerdedigers/middenvelders bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}]}'::jsonb),
('O10', 5, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Pirouette (Stap 5)\n- Aai achter standbeen (Stap 4)\n- De Schijntrap (Stap 4)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º (ZELFDE/ANDERE BEEN) IN STROOMVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nlinker/rechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Speler 3 speelt naar speler 4\n- idem als beschreven bij A.\nD. Speler 4 speelt naar speler 5\n- idem als beschreven bij B, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nMaterialen\nAantal spelers: 5-7\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "(3 : 1) OEFENING 3", "content": "Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nDe aanvaller die een fout maakt wordt verdediger\nUitvoering:\n- In spelvorm 5x samenspel = 1 pnt.\n- aanraken/afpakken of lijndribbel =1 pnt.\n- wisselen van taak bij 5 pnt.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 10m bij 8m\nDe 3 spelers nemen positie in op 3 van de 4\nzijden.\nDe verdediger neemt de positie in het midden in\nDe bal start bij de middelste man van de drie\naanvallers.\nAanwijzingen\nAanvallers coachen op:\n- het goed aanspeelbaar zijn aan beide zijden\nvan de speler in balbezit.\n- het goed vragen om de bal aan de kant van\nde bal.\n- het goed inspelen van de bal, voor de man,\nop de linker/rechter voet.\n- het zoveel mogelijk over de bal heen kijken.\nVerdediger coachen op:\n- Druk op de bal geven zodat de aanvallers\neen fout maken.\nPARTIJVORM 1:1\nMethodiek\nEén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}], "session_b": [{"type": "warming_up", "title": "STOKKENLOOP (1)", "content": "Is een oefening, waarbij de voorwaartse vormen worden\naangeleerd over de stokken. De oefening is opgebouwd van grove\nmotoriek naar de fijne motoriek. Dat wil zeggen binnen de\nlooptraining, er wordt gewerkt van een skipping naar skipping 45\ngraden en vervolgens naar kort voetenwerk.\nEr moet hierbij wel nadrukkelijk worden gelet op het lichtvoetig\nagreren over de stokken. Dat wil zeggen dat alles met de bal van\nde voet wordt uitgevoerd. Ten allen tijden wordt er op de bal van\nde voet gelopen.\nStap 1: Er wordt met de rechtervoet begonnen. De eerste stok\nwordt voorwaarts genomen en vervolgens wordt er met twee\nvoeten teruggestapt, de andere stokken worden gelopen met één\nvoet tussen de stokken.\nStap 2: Er wordt met de rechtervoet begonnen. De eerste en de\nderde stok worden voorwaarts genomen en vervolgens wordt er\nmet twee voeten teruggestapt, de andere stokken worden\ngelopen met één voet tussen de stokken.\nStap 3: Er wordt met de rechtervoet begonnen. De eerste, de\nderde en de vijfde stok worden voorwaarts genomen en\nvervolgens wordt er met twee voeten teruggestapt, de andere\nstokken worden gelopen met één voet tussen de stokken.\nDifferentiatie:\nLet op!\nDe romphouding moet recht zijn en er moet een duidelijke\narminzet aanwezig zijn.\nMaterialen\nAantal spelers: het gehele team.\nAantal stokkenparcours:\nEén, bij voorkeur twee.\nAantal pylonnen:\n12\nAantal stokken:\n5\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast."}, {"type": "techniek", "title": "A. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 4)\n- Akka (buiten-binnen) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken Schaar (Stap 4) en\nAkka (buiten-binnen) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VOOR JE: IN STROOMVORM", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\nDribbelen buitenkant voet:\n- Akka (buiten-binnen) (Stap 3A)\n- Schaar (Stap 5A)\nDribbelen buitenkant voet, inzet beweging binnenkant voet:\n- Aai buitenkant voet (Stap 5A)\n- Sleep (Stap 4A)\n- Akka (binnen-voor) (Stap 3A)\n- Uitstappen/meenemen (Stap 5A)\n- Akka (binnen-buiten) (Stap 3A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB. Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit.\nC. Daarna dribbelt hij, met de bal aan de voet, richting doel om\nvervolgens hierop af te ronden.\nD. Speler 1 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE -pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O10', 6, '{"session_a": [{"type": "warming_up", "title": "B. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 4)\n- Sleep (Stap 3)\n- Akka (binnen-voor) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 D: INGOOIEN, AANBIEDEN, TOT 135º IN RUIT/STROOMVORM", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar rechts\" aan.\n- Speler 1 gooit de bal in.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 pakt de bal op.\nC. Speler 3 speelt naar speler 4\n- Idem als beschreven bij A.\nD. Speler 4 speelt naar speler 5\n- Idem als beschreven bij B, etc.\nVariatie in uitvoering:\n- Idem, met rechts aannemen en met links spelen.\n- Idem, andersom met het andere been.\nVariatie in aanbieden:\n- Naar links\n- Voorwaarts\n- Achterwaarts\nMaterialen\nAantal spelers: 5-7\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nIngooi:\n- Beiden voeten houden contact met de\ngrond.\n- De bal achter het hoofd loslaten.\n- Beide handen op de bal houden.\n- Voeten in de richting van het gooien.\n- Op het juiste been ingooien.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "STAP 2.1 B: KOPPEN (SCHUIN) VANUIT ZITTENDE POSITIE", "content": "Met 2-tallen, waarbij speler 2 schuin t.o.v. speler 2 op de grond zit.\nA. Speler 1 speelt naar speler 2\n- speler 1 gooit de bal onderhands aan.\nB. Speler 2 speelt naar speler 1\n- speler 2 kopt de bal schuin terug , etc.\nVariatie in uitvoering:\n- idem, maar nu aangooien vanaf de ander kant.\nMaterialen\nAantal spelers: 2\nAantal ballen: per tweetal een bal\nOnderlinge afstand pylonen:\n1e jaars E-pupillen: 2 m\n2e jaars E-pupillen: 2 m\nDoordraaien:\n- wisselen van functie naar eigen inzicht.\nAanwijzingen\n- Bovenlichaam naar achteren, kin op de\nborst .\n- armen voor je houden.\n- juiste moment bovenlichaam naar voren en\narmen naar achter.\n- bal raken met het voorhoofd.\n- speler 2 krijgt de bal schuin aangegooid en\nwordt daardoor gedwongen om de bal ook\nschuin terug te koppen.\nLIJNDRIBBEL 2:1 MET DOEL\nMethodiek\nd.w.z. dat 2 aanvallers d.m.v. samenspel/ een persoonlijke actie\neen verdediger uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 2 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdediger kan de afgepakte bal scoren door de bal over de\nlijn aan de overkant te dribbelen.\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen:\nF-pupillen: 15m bij 10m\nE-pupillen: 18m bij 12m\nD-pupillen: 20m bij 15m\nC-,B-,A-junioren: 25m bij 20m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- keuzes maken aan de bal( 1:1 of overspelen)\n- rekening houden, bij het innemen van een\naanvallende positie, met de omschakeling bij\nbalverlies(restverdediging)\nVerdediger coachen op:\n- rekening houden met een goed zicht op de\npositie van de beide aanvallers bij het\ninnemen van een verdedigende positie(open\nstaan)\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel."}], "session_b": [{"type": "warming_up", "title": "KOE KOPEN", "content": "Oefening(en), waarbij de speler(s) voor elkaar staan met hun gezicht in de\nrichting van de finishlijn. De voorste speler geeft een tik op de hand van de\nspeler die achter hem staat en loopt vervolgens weg. De tik is het teken waarop\nde achterste speler de voorste speler mag proberen te tikken, voordat deze\nspeler de finishlijn heeft gepasseerd.\nOpgelet!\n- het is een reactiespel, waarbij de jongste jeugd spelenderwijs het spel wordt\naangeleerd.\n- later, bij de oudere jeugd, kan daar goed gebruik van worden gemaakt.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 4\nDe pylonen vormen een rechte lijn van 2 mtr.\nOrganisatie:\n- bij dit spel staan de spelers recht tegenover één speler die de leiding heeft.\nDeze speler bepaalt wanneer het spel begint."}, {"type": "techniek", "title": "C. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Uitstappen meenemen (Stap 4)\n- Akka (binnen-buiten) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken Uitstappen meenemen\n(Stap 4) en Akka (binnen-buiten) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "(4 : 2) OEFENING 1", "content": "Vier aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe aanvaller die een fout maakt wisselt van taak met de langst\nstaande verdediger.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 12m bij 10m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)\nPARTIJVORM 1:1\nMethodiek\nEén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}]}'::jsonb),
('O10', 7, '{"session_a": [{"type": "warming_up", "title": "DRIE IS TEVEEL", "content": "De spelers vormen naast elkaar staande tweetallen verspreid over\nhet hele vak. Twee spelers, 1 loper en 1 tikker vormen geen\ntweetal. De loper probeert de tikker te ontlopen en kan zich\ndaarbij vrijspelen door naast een tweetal te gaan staan.\nDe speler die aan de andere buitenkant komt te staan wordt\ndaardoor de nieuwe loper, die getikt moet worden.\nOpgelet!\nEen getikte speler wordt direct de nieuwe tikker.\nMaterialen\nDuur:10-15 min\nDuur ronde: 1 a 2 min\nAantal: 12 of meer spelers\nPylonen: 4 om het speelveld af te bakenen.\nAanwijzingen\n- De spelers moeten stil op hun plek blijven\nstaan"}, {"type": "techniek", "title": "STAP 2.1 D: AANBIEDEN, TOT 135º MET HET ZELFDE/ANDERE BEEN IN RUIT/STROOMVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechter/ linkervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de linker/\nrechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/ linkervoet aan.\nC. Speler 3 speelt naar speler 4\n- idem als beschreven bij A.\nD. Speler 4 speelt naar speler 5\n- idem als beschreven bij B, etc.\nVariatie in uitvoering:\n- idem, aannemen en spelen met het zelfde been.\nVariatie in aanbieden:\n- naar rechts\n- voorwaarts\n- achterwaarts\nMaterialen\nAantal spelers: 5-7\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "AANBIEDEN, TOT 135º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: alle\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}], "session_b": [{"type": "warming_up", "title": "SPIEGELEN (2)", "content": "Oefeningen, waarbij de speler(s) de door de tegenstander\nuitgevoerde stappen van de onderstaande technieken, in voor-,\nachter-, zijwaartse richting, nadoet(n).\n1. Tripling (Stap 3, 4)\n2. Skipping (Stap 4)\n3. Hielaanslag (Stap 2)\nOpgelet!\n- alleen uitvoeren als de spelers bekend zijn met bovenstaande\ntechnieken.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 2\nDe pylonen vormen een rechte lijn van 2 mtr.\nOrganisatie:\n- de spelers staan hierbij recht tegenover één\nspeler die de leiding heeft. Zij moeten daarbij\nzijn bewegingen volgen (spiegelen).\nAanwijzingen\n- Voor de beschrijving van de techniek, zie\ntechnieklijst.\nA. TEGENSTANDER NAAST JE: IN LIJNVORM\nMethodiek\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- De verandering (Stap 3)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "B. TEGENSTANDER NAAST JE: IN LIJNVORM HEEN TERUG", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt naar overstaande pylon.\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Kappen achter het standbeen (Stap 2)\n- Kappen binnenkant voet (Stap 3)\nC. Speler dribbelt terug en herhaald stap B bij de pylon.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nVERDEDIGEN DOOR AANVALLERS EN MIDDENVELDERS (4 : 5+KEEPER)\nMethodiek\nD.w.z. dat 4 aanvallers d.m.v. samenspel in balbezit moeten zien\nte komen, zonder het zo goed mogelijk positioneel verdedigen uit\nhet oog te verliezen.\nDe verdedigende partij (5 verdedigers /middenvelders+ Keeper)\nkan hierbij scoren door de bal over de lijn van één van de doeltjes\nte dribbelen.\nDe aanvallers kunnen in het grote doel scoren.\nDe oefening start altijd bij de doelman.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nMiddenvelders/aanvallers bij het verdedigen\ncoachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}]}'::jsonb),
('O10', 8, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER ACHTER JE: IN EEN VIERKANTSVORM", "content": "Spelers staan, zonder elkaar te hinderen, met de bal aan de voet,\nverspreid over de hele rechthoek.\nDe onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\n- De Overstap (Stap 3)\n- Kappen buitenkant voet (Stap 1+2)\n- Binnen-buitenkant wegdraai (Stap 1+2)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal pylonen: 4 op onderlinge afstand van 10\nmtr.\nAantal ballen: 6-9\nSpeelveld: rechthoek 20 bij 10 mtr.\nDoordraaien:\nIdem, maar nu de oefening met het andere been\nuitvoeren\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nSTAP 2.2 A: AANBIEDEN ZIJWAARTS, HEEN/TERUG IN LIJNVORM\nMethodiek\nA. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 1\n- speler 1 biedt zich \"naar rechts\" aan\n- speler 2 kaatst de bal met de binnenkant van de linkervoet terug.\nC. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 kaatst de bal met de binnenkant van de rechtervoet\nterug, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 4\nAantal ballen: 1\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "(3 : 1) OEFENING 3", "content": "Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nDe aanvaller die een fout maakt wordt verdediger\nUitvoering:\n- In spelvorm 5x samenspel = 1 pnt.\n- aanraken/afpakken of lijndribbel =1 pnt.\n- wisselen van taak bij 5 pnt.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 10m bij 8m\nDe 3 spelers nemen positie in op 3 van de 4\nzijden.\nDe verdediger neemt de positie in het midden in\nDe bal start bij de middelste man van de drie\naanvallers.\nAanwijzingen\nAanvallers coachen op:\n- het goed aanspeelbaar zijn aan beide zijden\nvan de speler in balbezit.\n- het goed vragen om de bal aan de kant van\nde bal.\n- het goed inspelen van de bal, voor de man,\nop de linker/rechter voet.\n- het zoveel mogelijk over de bal heen kijken.\nVerdediger coachen op:\n- Druk op de bal geven zodat de aanvallers\neen fout maken.\nPARTIJVORM 1:1\nMethodiek\nEén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}], "session_b": [{"type": "warming_up", "title": "TRIPLING MET BAL", "content": "Is een oefening, waarbij de speler de stap van de onderstaande\ntechniek uitvoert, terwijl hij zich voorwaarts beweegt. De speler\nraakt, bij elke voetplaatsing van de tripling, de bal met de punt\nvan de schoen en volgt zo de baan van de bal.\n1. Tripling (Stap 4)\nOpgelet!\nDit is een eindvorm, die alleen kan worden uitgevoerd als de\nspeler de laatste stap van de tripling voldoende beheerst.\nDifferentiatie:\nUitvoering in parcoursvorm, waarbij constant van richting moet\nworden veranderd.\nMaterialen\nAantal spelers: gehele team\nAantal ballen: aantal ballen aan aantal spelers\naanpassen.\nOrganisatie:\nDe spelers lopen van achterlijn tot 16-meterlijn\nin het 16-meter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "B. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 4)\n- Sleep (Stap 3)\n- Akka (binnen-voor) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Aai buitenkant voet\n(Stap 4), Sleep (Stap 3) en Akka (binnen-voor) (Stap 2).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VOOR JE: IN STROOMVORM", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\nDribbelen buitenkant voet:\n- Akka (buiten-binnen) (Stap 3A)\n- Schaar (Stap 5A)\nDribbelen buitenkant voet, inzet beweging binnenkant voet:\n- Aai buitenkant voet (Stap 5A)\n- Sleep (Stap 4A)\n- Akka (binnen-voor) (Stap 3A)\n- Uitstappen/meenemen (Stap 5A)\n- Akka (binnen-buiten) (Stap 3A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB. Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit.\nC. Daarna dribbelt hij, met de bal aan de voet, richting doel om\nvervolgens hierop af te ronden.\nD. Speler 1 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE -pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O10', 9, '{"session_a": [{"type": "warming_up", "title": "A. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 4)\n- Akka (buiten-binnen) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 C: INGOOIEN, AANBIEDEN, TOT 90º IN VIERKANT/STROOMVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 gooit de bal in\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 pakt de bal op.\nC. Speler 3 speelt naar speler 4\n- idem als beschreven bij A.\nD. Speler 4 speelt naar speler 5\n- idem als beschreven bij B, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been\n- idem, met rechts aannemen en met links spelen.\nVariatie in aanbieden:\n- Naar rechts\n- Achterwaarts\n- Voorwaarts\nMaterialen\nAantal spelers: 5-7\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nIngooi:\n- beide voeten houden contact met de grond\n- de bal achter het hoofd loslaten\n- beide handen op de bal houden\n- voeten in de richting van het gooien\n- op het juiste been ingooien.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "STAP 2.1 B: KOPPEN (SCHUIN) VANUIT ZITTENDE POSITIE", "content": "Met 2-tallen, waarbij speler 2 schuin t.o.v. speler 2 op de grond zit.\nA. Speler 1 speelt naar speler 2\n- speler 1 gooit de bal onderhands aan.\nB. Speler 2 speelt naar speler 1\n- speler 2 kopt de bal schuin terug , etc.\nVariatie in uitvoering:\n- idem, maar nu aangooien vanaf de ander kant.\nMaterialen\nAantal spelers: 2\nAantal ballen: per tweetal een bal\nOnderlinge afstand pylonen:\n1e jaars E-pupillen: 2 m\n2e jaars E-pupillen: 2 m\nDoordraaien:\n- wisselen van functie naar eigen inzicht.\nAanwijzingen\n- Bovenlichaam naar achteren, kin op de\nborst .\n- armen voor je houden.\n- juiste moment bovenlichaam naar voren en\narmen naar achter.\n- bal raken met het voorhoofd.\n- speler 2 krijgt de bal schuin aangegooid en\nwordt daardoor gedwongen om de bal ook\nschuin terug te koppen.\nLIJNDRIBBEL 3:2 MET DOEL\nMethodiek\nd.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}], "session_b": [{"type": "warming_up", "title": "OMSCHAKELING MET BAL (2)", "content": "Bij deze oefening wordt de omschakeling van voetballers getraind.\nDe spelers worden hierbij in 2 groepen van elk 6 spelers verdeeld. Eén groep is\nvoorzien van een hesje. Elke speler uit de ene groep vormt een tweetal met een\nspeler uit de andere groep.\nBij dit spel brengen de spelers van de ene groep de bal buiten de middencirkel\n(niet schieten). De andere spelers van elk tweetal uit de andere groep pakken de\nbal weer op en brengen deze weer naar de middencirkel.\nWelk tweetal heeft als eerste 5 ballen bij elkaar?\nOpgelet!\n- dit zijn introductievormen bij de looptraining.\nMaterialen\nAantal spelers: 12\nOrganisatie:\n- middencirkel.\nTEGENSTANDER VOOR JE: IN EEN Y-VORM\nMethodiek\nDe onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 maakt de beweging\n- Speler 1 voert de \"Aai-buitenkantvoet\" (Stap 5A) uit.\nC. Speler 1 dribbelt naar speler 2\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 2.\n- Speler 2 neemt de bal aan en voert nu dezelfde oefening, met\nhet andere been, uit.\nIdem voor de spelers 4,5 en 6.\nMaterialen\nAantal spelers: 6\nAantal ballen; 2\nAantal pylonen: 5\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening, met het andere\nbeen, in tegenovergestelde richting uit. Daarna\nneemt deze speler de plaats in van speler 3, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "1. (3 : 1 + 2)", "content": "Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nWanneer de verdediger de bal onderschept dan moet hij de\nruimte zoeken met een lange pass naar het andere vak om\nzodoende het spel te verleggen.\nTevens gaan 1 verdediger en 1 aanvaller mee naar het andere\nveld. Nu moeten de drie verdedigers d.m.v. samenspel de bal in\nhun bezit zien te houden zonder dat de aanvaller de bal kan\nveroveren. Etc.\nVariatie in aanbieding:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 6\nAfstand tussen de pylonen: 2x (10m bij 8m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- omschakeling van balbezit naar balverlies\n- druk op de bal geven zodat de aanvallers\neen fout maken"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O10', 10, '{"session_a": [{"type": "warming_up", "title": "B. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 4)\n- Sleep (Stap 3)\n- Akka (binnen-voor) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 D: AANBIEDEN, TOT 135º (ZELFDE/ANDERE BEEN) IN RUITVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Speler 3 speelt naar speler 4\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, aannemen en spelen met het zelfde been.\nVariatie in aanbieden:\n- naar rechts\n- voorwaarts\n- achterwaarts\nVariatie\nVariatie 3: Aanbieden voorwaarts, achterwaarts, rechts en links\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "AANBIEDEN, TOT 135º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: alle\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2", "content": "Twee aanvallers moeten d.m.v. samenspel/ individuele actie 2\nverdedigers uitspelen, om daarna in één van de twee\ntegenoverstaande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 10m bij 15m\nE-pupillen: 12m bij 18m\nD-pupillen: 15m bij 20m\nC-junioren: 20m bij 25m\nB-,A-junioren: 25m bij 30m\nDoel: 4 (2 mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen, om daarna in één van de twee\ntegenoverstaande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers: 6\nAantal ballen: veel\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2 mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering."}], "session_b": [{"type": "test", "title": "SPEEDLADDER (1)", "content": "Is een oefening, waarbij de voorwaartse vormen worden\naangeleerd in de speedladder. De oefening is opgebouwd van\ngrove motoriek naar de fijne motoriek. Dat wil zeggen binnen de\nlooptraining, er wordt gewerkt van een skipping naar skipping 45\ngraden en vervolgens naar kort voetenwerk.\nStap 1: Eén voetje in het raam plaatsen.\nStap 2: Twee voetjes in het raam plaatsen.\nStap 3: Drie voetjes in het raam plaatsen.\nDifferentiatie:\nStroop de ladder op, zodat er door de spelers ten alle tijden een\nskipping ingezet moet worden.\nLet op!\nDeze vormen kunnen spelenderwijs worden aangeleerd.\nMaterialen\nAantal spelers: het gehele team.\nAantal speedladders:\nEén, bij voorkeur twee.\nAantal pylonnen:\nEén\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast."}, {"type": "techniek", "title": "TEGENSTANDER VOOR JE: IN EEN PLUSVORM (BINNEN)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet,\ninzet beweging binnenkant rechter voet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Sleep (Stap 4A)\n- Akka (binnen-voor) (Stap 3A)\n- Uitstappen/meenemen (Stap 5A)\n- Akka (binnen-buiten) (Stap 3A)\nC. Speler 1 dribbelt naar speler 2\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 2.\n- Speler 2 neemt de bal aan en voert nu dezelfde oefening, met\nhet andere been, uit.\nIdem voor de spelers 4,5 en 6.\nVariatie:\nEen dubbele schaarbeweging door 2x om de bal heen te bewegen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 6\nAantal ballen; 2\nAantal pylonen: 5\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening, met het andere\nbeen, in tegenovergestelde richting uit. Daarna\nneemt deze speler de plaats in van speler 3, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "AANVALLEN DOOR MIDDENVELDERS EN AANVALLERS (5 : 4+KEEPER) KLEIN VELD", "content": "D.w.z. dat 5 aanvallers/ middenvelders d.m.v. samenspel kansen\ncreëren.\nDe 4 verdedigers /middenvelders+ keeper kunnen scoren door de\nbal over de lijn van één van de kleine doetjes te dribbelen.\nDe aanvallers kunnen op het grote doel scoren.\nDe oefening start altijd bij de aanvallers.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nMiddenvelders/aanvallers bij aanvallen\ncoachen op:\n- het samenspelen vanuit een halve kom\n- het opkomen van de middenvelder\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (7+11)\n- het loskomen van de tegenstander d.m.v.\nvooracties.\n- het creëren van een twee tegen een situatie.\nMiddenvelders/aanvallers bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)\n- het direct druk zetten op de bal."}, {"type": "partijvorm", "title": "PARTIJVORM 5:5 (2)", "content": "Vijf aanvallers moeten d.m.v. samenspel/ individuele actie 5\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers: 10(15)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 30m bij 25m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-junioren: 5m bij 2m\nDoordraaien:\n- het winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\n- geen score na twee minuten, dan wordt de\nlangst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}]}'::jsonb),
('O10', 11, '{"session_a": [{"type": "warming_up", "title": "C. TEGENSTANDER VOOR JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Uitstappen meenemen (Stap 4)\n- Akka (binnen-buiten) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.2 A: AANBIEDEN, HEEN/TERUG IN LIJNVORM COMBINATIE", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 1 speelt de bal met de binnenkant van de linker-\n/rechtervoet.\nB. Speler 2 speelt naar speler 1\n- speler 1 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 2 kaatst de bal met de binnenkant van de linker-\n/rechtervoet terug.\nC. Speler 1 speelt naar speler 2\n- speler 2 biedt zich in een zelf gekozen aanbiedingsvorm aan\n- speler 1 kaatst de bal met de binnenkant van de linker-\n/rechtervoet.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nMaterialen\nAantal spelers: 2\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten.\n(4 : 2) OEFENING 2\nMethodiek\nVier aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe verdediger moet na het veroveren van de bal d.m.v. lijndribbel\nscoren over de korte zijden(omschakeling).\nDe aanvaller die de fout maakt wordt verdediger.\nWisselen van taak: De verdediger die het langst in het midden\nheeft gestaan wisselt met de aanvaller die de fout heeft gemaakt\nof hij wisselt met de langst staande aanvaller.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 12m bij 10m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "TRIPLING MET BAL", "content": "Is een oefening, waarbij de speler de stap van de onderstaande\ntechniek uitvoert, terwijl hij zich voorwaarts beweegt. De speler\nraakt, bij elke voetplaatsing van de tripling, de bal met de punt\nvan de schoen en volgt zo de baan van de bal.\n1. Tripling (Stap 4)\nOpgelet!\nDit is een eindvorm, die alleen kan worden uitgevoerd als de\nspeler de laatste stap van de tripling voldoende beheerst.\nDifferentiatie:\nUitvoering in parcoursvorm, waarbij constant van richting moet\nworden veranderd.\nMaterialen\nAantal spelers: gehele team\nAantal ballen: aantal ballen aan aantal spelers\naanpassen.\nOrganisatie:\nDe spelers lopen van achterlijn tot 16-meterlijn\nin het 16-meter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nSKIPPING MET BAL\nMethodiek\nIs een oefening, waarbij de speler de stappen van de\nonderstaande techniek, op de plaats, uitvoert, terwijl hij een bal in\nbeide handen voor zich houdt.Bij elke stap van de skipping raakt\nde speler bij het heffen van zijn knie met zijn bovenbeen de bal.\n1. Skipping (Stap 3 en 4)\nOpgelet!\n- dit is een eindvorm. Deze vorm kan alleen worden uitgevoerd als\nde speler de stappen 3 en 4 van de skipping beheerst.\nDifferentiatie:\n- uitvoering in voorwaartse richting.\nMaterialen\nAantal spelers: gehele team.\nAantal ballen: aantal ballen aan aantal spelers\naanpassen.\nOrganisatie:\n- de spelers lopen van 5-meterlijn tot 16-\nmeterlijn in het 16-meter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek, zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VOOR JE: IN EEN PLUSVORM (BUITEN)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 5A)\n- Akka (buiten-binnen) (Stap 3A)\nC. Speler 1 dribbelt naar speler 2\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 2.\n- Speler 2 neemt de bal aan en voert nu dezelfde oefening, met\nhet andere been, uit.\nIdem voor de spelers 4,5 en 6.\nVariatie:\nEen dubbele schaarbeweging door 2x om de bal heen te bewegen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 6\nAantal ballen; 2\nAantal pylonen: 5\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening, met het andere\nbeen, in tegenovergestelde richting uit. Daarna\nneemt deze speler de plaats in van speler 3, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "AANBIEDEN, TOT 90º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: alle\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O10', 12, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER NAAST JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- De verandering (Stap 3)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER NAAST JE: IN LIJNVORM HEEN TERUG", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt naar overstaande pylon.\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Kappen achter standbeen (Stap 2)\n- Kappen binnenkant voet (Stap 3)\n- Kappen buitenkant voet (Stap 3)\n- De Overstap (Stap 4)\nC. Speler dribbelt terug en herhaald stap B bij de pylon.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 D: INGOOIEN, AANBIEDEN, TOT 135º IN RUIT/STROOMVORM", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar rechts\" aan.\n- Speler 1 gooit de bal in.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 pakt de bal op.\nC. Speler 3 speelt naar speler 4\n- Idem als beschreven bij A.\nD. Speler 4 speelt naar speler 5\n- Idem als beschreven bij B, etc.\nVariatie in uitvoering:\n- Idem, met rechts aannemen en met links spelen.\n- Idem, andersom met het andere been.\nVariatie in aanbieden:\n- Naar links\n- Voorwaarts\n- Achterwaarts\nMaterialen\nAantal spelers: 5-7\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nIngooi:\n- Beiden voeten houden contact met de\ngrond.\n- De bal achter het hoofd loslaten.\n- Beide handen op de bal houden.\n- Voeten in de richting van het gooien.\n- Op het juiste been ingooien.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "STAP 2.1 B: KOPPEN (SCHUIN) VANUIT ZITTENDE POSITIE", "content": "Met 2-tallen, waarbij speler 2 schuin t.o.v. speler 2 op de grond zit.\nA. Speler 1 speelt naar speler 2\n- speler 1 gooit de bal onderhands aan.\nB. Speler 2 speelt naar speler 1\n- speler 2 kopt de bal schuin terug , etc.\nVariatie in uitvoering:\n- idem, maar nu aangooien vanaf de ander kant.\nMaterialen\nAantal spelers: 2\nAantal ballen: per tweetal een bal\nOnderlinge afstand pylonen:\n1e jaars E-pupillen: 2 m\n2e jaars E-pupillen: 2 m\nDoordraaien:\n- wisselen van functie naar eigen inzicht.\nAanwijzingen\n- Bovenlichaam naar achteren, kin op de\nborst .\n- armen voor je houden.\n- juiste moment bovenlichaam naar voren en\narmen naar achter.\n- bal raken met het voorhoofd.\n- speler 2 krijgt de bal schuin aangegooid en\nwordt daardoor gedwongen om de bal ook\nschuin terug te koppen.\nLIJNDRIBBEL 3:2 MET DOEL\nMethodiek\nd.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}], "session_b": [{"type": "warming_up", "title": "STOKKENLOOP TIKKERTJE", "content": "Bij deze oefening staan de spelers verdeeld in 2 groepen van elk 6 spelers\ntegenover elkaar aan beide zijden van het “stokken-parcours”.\nAan het eind van beide parcoursen staan twee verschillend gekleurde pylonen\nmet aan weerszijden op 10 meter afstand daarvan nog een pylon.\nEr wordt tegelijkertijd gestart met het stokkenparcours(foutloos lopen, anders\nopnieuw).\nDe eerste aangekomene tikt een pylon aan en kiest vervolgens een richting.\nDe laatst aangekomene moet nadat hij de pylon heeft aangetikt de ander\nproberen in te halen en te tikken.\nLet op!\nBij beheersing van het stokkenparcours kan er op snelheid wordt gewerkt.\nMaterialen\nAantal spelers: 12\nAantal pylonen: 24\nOrganisatie:\nDe spelers staan tegenover elkaar met een ruimte er tussen van 20 á 25 meter.\nDe onderlinge afstanden van het stokkenparcours moet even groot zijn."}, {"type": "techniek", "title": "TEGENSTANDER NAAST JE: IN EEN PLUSVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- De verandering (Stap 4A)\n- Kappen binnenkant (Stap 4A)\n- Kappen buitenkant voet (Stap 4A)\n- Kappen achter het standbeen (Stap 3A)\n- De Overstap (Stap 5A)\nC. Speler 1 dribbelt naar speler 2\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 2.\n- Speler 2 neemt de bal aan en voert nu dezelfde oefening uit.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 8-12\nAantal ballen: 4\nAantal pylonen: 5\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 geeft de bal aan speler 2 enz.\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "1. (2 : 1)", "content": "REGELS:\n• Twee aanvallers moeten d.m.v. samenspel de bal in hun bezit\nzien te houden zonder dat de verdediger de bal kan veroveren.\n• Direct na verovering van de bal moet de verdediger wisselen\nvan taak met de aanvaller van wie hij de bal heeft veroverd.\nVARIATIE IN UITVOERING:\n• de aanvallers mogen de bal maar 2x raken.\nMaterialen\nMATERIALEN:\n• Aantal spelers: 3\n• Aantal ballen: 1\n• Aantal pylonen: 4\n• Afstand tussen de pylonen: 10m bij 8m\nAanwijzingen\nAANVALLERS COACHEN OP:\n• het vrijlopen en aanspeelbaar zijn, zonder\nbal\n• het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n• het altijd in beweging zijn van de bal en de\nspeler\n• het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n• het vragen om de bal\n• het nacoachen van de bal/ pass\nVERDEDIGER COACHEN OP:\n• het rekening houden met een goed zicht op\nde posities van de aanvallers\n• het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O10', 13, '{"session_a": [{"type": "warming_up", "title": "FLUIT / NUMMERSPEL", "content": "Elke speler dribbelt met een bal door het vak. De trainer gebruikt de vooraf aan\ngegeven tekens.\nBij het fluiten of het roepen van een nummer moeten de spelers de daarbij\nbehorende afgesproken tekens uitvoeren, zoals:\n- Naar de zijkant dribbelen\n- Een kapbeweging maken\n- De bal stil leggen onder de voet\n- Een versnelling maken met de bal aan de voet\n- De bal hooghouden.\n- Op de bal zitten\n- Wisselen van bal met een andere speler.\nOpgelet!\nMaak er een puntenspel van.\nWie behaalt de minste strafpunten?\nMaterialen\nTijd: 10-15 min\nRonde tijden: 1 a 2 min\nPylonen: 4 pylonen om het speelveld uit te zetten\nBallen: iedere speler heeft een bal."}, {"type": "techniek", "title": "STAP 2.2 B: AANBIEDEN, TOT 45º IN DRIEHOEKSVORM (1)", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich opengedraaid \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich opengedraaid \"naar links\" aan\n- speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\nC. Speler 3 speelt naar speler 1\n- speler 1 biedt zich opengedraaid \"naar links\" aan\n- speler 1 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 1, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "AANBIEDEN, TOT 45º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: 4-6\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2", "content": "Twee aanvallers moeten d.m.v. samenspel/ individuele actie 2\nverdedigers uitspelen, om daarna in één van de twee\ntegenoverstaande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 10m bij 15m\nE-pupillen: 12m bij 18m\nD-pupillen: 15m bij 20m\nC-junioren: 20m bij 25m\nB-,A-junioren: 25m bij 30m\nDoel: 4 (2 mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen, om daarna in één van de twee\ntegenoverstaande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers: 6\nAantal ballen: veel\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2 mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering."}], "session_b": [{"type": "warming_up", "title": "KOE KOPEN", "content": "Oefening(en), waarbij de speler(s) voor elkaar staan met hun gezicht in de\nrichting van de finishlijn. De voorste speler geeft een tik op de hand van de\nspeler die achter hem staat en loopt vervolgens weg. De tik is het teken waarop\nde achterste speler de voorste speler mag proberen te tikken, voordat deze\nspeler de finishlijn heeft gepasseerd.\nOpgelet!\n- het is een reactiespel, waarbij de jongste jeugd spelenderwijs het spel wordt\naangeleerd.\n- later, bij de oudere jeugd, kan daar goed gebruik van worden gemaakt.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 4\nDe pylonen vormen een rechte lijn van 2 mtr.\nOrganisatie:\n- bij dit spel staan de spelers recht tegenover één speler die de leiding heeft.\nDeze speler bepaalt wanneer het spel begint."}, {"type": "techniek", "title": "TEGENSTANDER NAAST JE: IN EEN DRIEHOEKVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Kappen binnenkant(Stap 3)\n- Kappen buitenkant voet (Stap 3)\n- Kappen achter het standbeen (Stap 2)\n- De Overstap (Stap 4)\nC. Speler 1 dribbelt weer terug\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nD. Speler 1 voert één van de onderstaande bewegingen uit:\n- Kappen binnenkant(Stap 3)\n- Kappen buitenkant voet (Stap 3)\n- Kappen achter het standbeen (Stap 2)\n- De Overstap (Stap 3)\nE. Speler 1 dribbelt richting middelste pylon.\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nF. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan..\nG. Speler 2 dribbelt naar speler 6.\n- Speler 2 dribbelt de bal met de buitenkant van de linkervoetvoet\nIdem voor de spelers 3,4 en 5.\nMaterialen\nAantal spelers: 6\nAantal ballen: 2\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.(in de vorm\nvan een dubbele driehoek).\nDoordraaien:\n- Speler 1 geeft de bal aan speler 2. Speler 2\ngeeft de bal aan speler 3, enz.\n- Idem voor de spelers 4, 5 en 6 aan de andere\nkant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "AANVALLEN DOOR MIDDENVELDERS EN AANVALLERS (5 : 4+KEEPER) KLEIN VELD", "content": "D.w.z. dat 5 aanvallers/ middenvelders d.m.v. samenspel kansen\ncreëren.\nDe 4 verdedigers /middenvelders+ keeper kunnen scoren door de\nbal over de lijn van één van de kleine doetjes te dribbelen.\nDe aanvallers kunnen op het grote doel scoren.\nDe oefening start altijd bij de aanvallers.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nMiddenvelders/aanvallers bij aanvallen\ncoachen op:\n- het samenspelen vanuit een halve kom\n- het opkomen van de middenvelder\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (7+11)\n- het loskomen van de tegenstander d.m.v.\nvooracties.\n- het creëren van een twee tegen een situatie.\nMiddenvelders/aanvallers bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)\n- het direct druk zetten op de bal."}, {"type": "partijvorm", "title": "PARTIJVORM 5:5 (2)", "content": "Vijf aanvallers moeten d.m.v. samenspel/ individuele actie 5\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers: 10(15)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 30m bij 25m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-junioren: 5m bij 2m\nDoordraaien:\n- het winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\n- geen score na twee minuten, dan wordt de\nlangst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}]}'::jsonb),
('O10', 14, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Pirouette (Stap 5)\n- Aai achter standbeen (Stap 4)\n- De Schijntrap (Stap 4)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 D: AANBIEDEN, TOT 135º IN Y-VORM", "content": "A. Speler 1 speelt naar speler 2.\n- speler 2 biedt zich \"voorwaarts\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Spelers 3 dribbelt met de bal naar speler 8.\n- speler 3 wisselt van kant ensluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\nIdem aan de andere kant voor de spelers 5 t/m 8, alleen dan met\nlinks uitvoeren.\nVariatie in uitvoering:\n- aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nVariatie in aanbieden:\n- naar rechts\n- naar links\n- achterwaarts\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 4\nAfstand van pylonen:\n1 ste jaars F-pupillen: 5 m\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- wisselen door in de andere rij aan te sluiten.\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "1. (3 : 1 + 2)", "content": "Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nWanneer de verdediger de bal onderschept dan moet hij de\nruimte zoeken met een lange pass naar het andere vak om\nzodoende het spel te verleggen.\nTevens gaan 1 verdediger en 1 aanvaller mee naar het andere\nveld. Nu moeten de drie verdedigers d.m.v. samenspel de bal in\nhun bezit zien te houden zonder dat de aanvaller de bal kan\nveroveren. Etc.\nVariatie in aanbieding:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 6\nAfstand tussen de pylonen: 2x (10m bij 8m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- omschakeling van balbezit naar balverlies\n- druk op de bal geven zodat de aanvallers\neen fout maken"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "SPIEGELEN (2)", "content": "Oefeningen, waarbij de speler(s) de door de tegenstander\nuitgevoerde stappen van de onderstaande technieken, in voor-,\nachter-, zijwaartse richting, nadoet(n).\n1. Tripling (Stap 3, 4)\n2. Skipping (Stap 4)\n3. Hielaanslag (Stap 2)\nOpgelet!\n- alleen uitvoeren als de spelers bekend zijn met bovenstaande\ntechnieken.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 2\nDe pylonen vormen een rechte lijn van 2 mtr.\nOrganisatie:\n- de spelers staan hierbij recht tegenover één\nspeler die de leiding heeft. Zij moeten daarbij\nzijn bewegingen volgen (spiegelen).\nAanwijzingen\n- Voor de beschrijving van de techniek, zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN EEN PLUSVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- 2x kappen buitenkant voet (Stap 4A)\n- Pirouette (Stap 6A)\n- Aai-kappen achter het standbeen (Stap 5A)\n- de Schijntrap (Stap 5A)\nC. Speler 1 dribbelt naar speler 2\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 2.\n- Speler 2 neemt de bal aan en voert nu, met het andere been, in\ntegengestelde richting dezelfde oefening uit.\n- Speler 2 geeft de bal aan speler 3, etc.\nIdem voor de spelers 4,5 en 6.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 6\nAantal ballen: 2\nAantal pylonen: 5\nOnderlinge afstand pylonen: 10 mtr. tot de\nmiddelste pylon\nDoordraaien:\n- Speler 1 geeft de bal aan speler 2. Deze speler\nvoert de oefening met het andere been in\ntegenovergestelde richting uit en geeft de bal\naan speler 3. Enz.\n- Idem voor de spelers 4,5 en 6.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 C: DOORKOPPEN VANUIT ZITTENDE POSITIE", "content": "Met 3-tallen, waarbij de aangooiende/ ontvangende spelers 1 en 3\neen staande positie innemen en speler 2 op de grond zit.\nA. Speler 1 speelt naar speler 2\n- speler 1 gooit de bal onderhands aan.\nB. Speler 2 speelt naar speler 3\n- speler 2 kopt de bal schuin door , etc.\nMaterialen\nAantal spelers: 3\nAantal ballen: per drietal een bal\nAfstand van pylonen:\n1e jaars E-pupillen: 2 m\n2e jaars E-pupillen: 2 m\nDoordraaien:\n- wisselen van functie naar eigen inzicht\nAanwijzingen\n- bovenlichaam naar achteren, kin op de\nborst .\n- armen voor je houden.\n- juiste moment bovenlichaam naar voren en\narmen naar achter.\n- bal raken met het voorhoofd.\n- de bal goed richting geven, door de\nduwbeweging in de richting van speler 3 te\nmaken.\nLIJNDRIBBEL 3:2 MET DOEL\nMethodiek\nd.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}]}'::jsonb),
('O10', 15, '{"session_a": [{"type": "warming_up", "title": "KETTINGTIKKERTJE", "content": "Bij dit spel staan alle spelers, met een bal aan de voet, in een vak. Twee spelers\nzijn de tikkers en moeten proberen de spelers uit te tikken door hun bal uit het\nspel te schieten.\nDe eerst afgetikte speler pakt, nadat zijn bal is uitgeschoten de hand van de\ntikker vast. Elke volgende afgetikte speler sluit daarna aan om zo een ketting te\nvormen.\nWelke verdediger behaalt de langste ketting (ofwel wie werken het beste samen?)\nOpmerking:\n- als tijdens het tkken de ketting breekt, dan mag de afgetikte speler gewoon\ndoorspelen.\nLet op:\n- de kettinggrootte mag niet groter worden dan 4 spelers (bij het vaststellen van\nhet resultaat wordt dan het totaal aantal afgetikte spelers geteld).\nMaterialen\nPylonen: 4 pylonen om het speelveld uit te zetten.\nBallen: op een speler na heeft iedere speler een bal\nSpeeltijd: 10- 15 minuten"}, {"type": "techniek", "title": "STAP 2.2 B: AANBIEDEN, TOT 45º IN DRIEHOEKSVORM (2)", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich opengedraaid \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich opengedraaid \"naar links\" aan\n- speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\nC. Speler 3 speelt naar speler 1\n- speler 1 biedt zich opengedraaid \"naar links\" aan\n- speler 1 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 1, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nMaterialen\nAantal spelers: 4-5\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- A1, B1 en C1: Achter de bal aan doorlopen naar\nde volgende pylon.\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "(4 : 2) OEFENING 2", "content": "Vier aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe verdediger moet na het veroveren van de bal d.m.v. lijndribbel\nscoren over de korte zijden(omschakeling).\nDe aanvaller die de fout maakt wordt verdediger.\nWisselen van taak: De verdediger die het langst in het midden\nheeft gestaan wisselt met de aanvaller die de fout heeft gemaakt\nof hij wisselt met de langst staande aanvaller.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 12m bij 10m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "test", "title": "WENDBAARHEIDSTEST 1", "content": "Voor deze test wordt in het strafschopgebied, tussen de doellijn\nen de rand van het gebied, een parcours ( zie tekening) uitgezet.\nHet protocol voor deze test luidt als volgt:\nDe test start vanuit buikligging. Vervolgens wordt het hele traject\nin korte sprintjes, van pylon naar pylon, afgelegd.\nDe pylonen worden daarbij,tot het bereiken van de finish, telkens\nzo kort mogelijk gerond.\nMaterialen\nAantal spelers: alle spelers\nAantal pylonen:8\nAfstand tussen de pylonen:gebruik de\naangegeven lijnen en verdeel de tussenliggende\nruimte gelijkmatig\nSchrijfbenodigdheden\nAanwijzingen\n- ontwikkel, zowel heen als terug, een zo\nhoog mogelijke snelheid\n- draai kort om de pylon\n- neem minimaal 2-3 minuten rust tussen\ntwee testen\nSPRINTTEST\nMethodiek\nVoor deze test wordt in de breedte van het strafschopgebied, op\neen onderlinge afstand van tekens 10 meter, met 5 pylonen een\nparcours uitgezet.\nDe spelers starten de sprint vanaf de zijkant van het “16-\nmetergebied” vanuit stilstand en sprinten vervolgens om de\neerste pylon heen weer terug, gevolgd door een sprint om de\ntweede pylon heen en weer terug. Idem om de derde en de vierde\npylon.\nDe behaalde eindtijd wordt gemeten en vastgelegd.\nMaterialen\nAantal spelers: alle spelers\nAantal pylonen: 5\nAfstand tussen de pylonen: 10 mtr.\n1 stopwatch\nSchrijfbenodigdheden.\n- deze test heeft tot doel om de “reactie/\nacceleratie- en/of de maximale snelheid” te\ntoetsen/meten.\nAanwijzingen\n- zowel heen als terug een zo hoog mogelijke\nsnelheid ontwikkelen\n- kort om de pylon draaien\n- neem minimaal 2-3 minuten rust tussen\ntwee testen."}, {"type": "techniek", "title": "AANBIEDEN, TOT 135º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: alle\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2", "content": "Twee aanvallers moeten d.m.v. samenspel/ individuele actie 2\nverdedigers uitspelen, om daarna in één van de twee\ntegenoverstaande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 10m bij 15m\nE-pupillen: 12m bij 18m\nD-pupillen: 15m bij 20m\nC-junioren: 20m bij 25m\nB-,A-junioren: 25m bij 30m\nDoel: 4 (2 mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen, om daarna in één van de twee\ntegenoverstaande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers: 6\nAantal ballen: veel\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2 mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering."}]}'::jsonb),
('O10', 16, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER ACHTER JE: IN EEN LIJNVORM", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de voet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan (deze doet alsof hij een speler in de rug heeft).\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Binnen-buitenkant wegdraai (Stap 4)\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\nC. Speler 1 dribbelt naar speler 6\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 6.\nIdem voor de spelers 4,5 en 6 in tegengestelde richting, etc.\nVariatie:\nIdem, maar nu met het andere been uitvoeren.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 6\nAantal ballen; 2\nAantal pylonen: 3\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt, na de pass op speler 2, diens\nplaats in. Speler 2 dribbelt naar speler 6 en geeft\nhem de bal. Speler 4 neemt, na de pass op\nspeler 5, diens plaats in en speler 5 geeft de bal\naan speler 3, etc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN LIJNVORM HEEN TERUG", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt naar overstaande pylon.\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Kappen buitenkant voet (Stap 3)\n- Binnen-buitenkant wegdraai (Stap 3)\n- De Overstap (Stap 4)\nC. Speler dribbelt terug en herhaald stap B bij de pylon.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 D: AANBIEDEN, TOT 135º (ZELFDE/ANDERE BEEN) IN RUITVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Speler 3 speelt naar speler 4\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, aannemen en spelen met het zelfde been.\nVariatie in aanbieden:\n- naar rechts\n- voorwaarts\n- achterwaarts\nVariatie\nVariatie 3: Aanbieden voorwaarts, achterwaarts, rechts en links\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "OPBOUW DOOR VERDEDIGERS EN MIDDENVELDER (5+KEEPER : 4) KLEIN VELD", "content": "D.w.z. dat 5 verdedigers / middenvelders + keeper d.m.v.\nsamenspel 4 aanvallers/ middenvelders uitspelen, om daarna te\nscoren door de bal over de lijn van een van de doeltjes te\ndribbelen.\nDe aanvallers kunnen de afgepakte bal scoren op het grote doel.\nDe opbouw start altijd bij de doelman.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nSpelers te kort! Zorg dan dat je opbouwende\npartij een speler meer heeft.\nAanwijzingen\nVerdedigers/middenvelders bij opbouw\ncoachen op:\n- het breed maken van het veld door de\nverdedigers. Wordt één van de verdedigers\nin gespeeld dan knijpt de ander naar binnen\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (2+5)\n- het diep weglopen, om ruimte te maken,\nvan de centrale middenvelder\n- het benutten van een overtalsituatie\nVerdedigers/middenvelders bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}], "session_b": [{"type": "warming_up", "title": "OMSCHAKELINGSTIKKERTJE", "content": "Bij deze oefening wordt de omschakeling van voetballers getraind.\nDe spelers worden hierbij in 2 groepen van elk 6 spelers verdeeld. Eén groep is\nvoorzien van een hesje. Elke speler uit de ene groep vormt een tweetal met een\nspeler uit de andere groep.\nOp een teken van de trainer probeert de speler uit de ene groep de andere\nspeler van het tweetal uit de andere groep te tikken.\nNadat hij hem getikt heeft draait hij direct van hem weg en versnelt naar de\nzijlijn. De andere speler probeert op zijn beurt de eerste speler, nog voordat hij\nde zijlijn heeft gepasseerd, te tikken.\nDifferentiatie gemakkelijk:\n- het spel “koe-kopen”.\nDifferentiatie moeilijk:\n- er kan gevarieerd worden door spelers met een bal aan de zijlijn te laten staan,\nom een kaats aan te gaan met de weggedraaide speler. Hij komt hierbij als het\nware in de bal. Omschakeling met bal (1)\nOpgelet!\n- dit zijn introductievormen bij de looptraining.\nMaterialen\nAantal spelers: 12\nOrganisatie:\n- de afmeting van het vak is 10 bij 15 meter."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN EEN LIJNVORM", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de voet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan (deze doet alsof hij een speler in de rug heeft).\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Binnen-buitenkant wegdraai (Stap 4)\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\nC. Speler 1 dribbelt naar speler 6\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 6.\nIdem voor de spelers 4,5 en 6 in tegengestelde richting, etc.\nVariatie:\nIdem, maar nu met het andere been uitvoeren.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 6\nAantal ballen; 2\nAantal pylonen: 3\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt, na de pass op speler 2, diens\nplaats in. Speler 2 dribbelt naar speler 6 en geeft\nhem de bal. Speler 4 neemt, na de pass op\nspeler 5, diens plaats in en speler 5 geeft de bal\naan speler 3, etc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN LIJNVORM HEEN TERUG", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt naar overstaande pylon.\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Kappen buitenkant voet (Stap 3)\n- Binnen-buitenkant wegdraai (Stap 3)\n- De Overstap (Stap 4)\nC. Speler dribbelt terug en herhaald stap B bij de pylon.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken De Overstap (Stap 4),\nKappen buitenkant voet (Stap 3) en Binnen buiten wegdraai (Stap\n3+4).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n1. (2 : 1)\nMethodiek\nREGELS:\n• Twee aanvallers moeten d.m.v. samenspel de bal in hun bezit\nzien te houden zonder dat de verdediger de bal kan veroveren.\n• Direct na verovering van de bal moet de verdediger wisselen\nvan taak met de aanvaller van wie hij de bal heeft veroverd.\nVARIATIE IN UITVOERING:\n• de aanvallers mogen de bal maar 2x raken.\nMaterialen\nMATERIALEN:\n• Aantal spelers: 3\n• Aantal ballen: 1\n• Aantal pylonen: 4\n• Afstand tussen de pylonen: 10m bij 8m\nAanwijzingen\nAANVALLERS COACHEN OP:\n• het vrijlopen en aanspeelbaar zijn, zonder\nbal\n• het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n• het altijd in beweging zijn van de bal en de\nspeler\n• het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n• het vragen om de bal\n• het nacoachen van de bal/ pass\nVERDEDIGER COACHEN OP:\n• het rekening houden met een goed zicht op\nde posities van de aanvallers\n• het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O10', 17, '{"session_a": [{"type": "warming_up", "title": "FLUIT / NUMMERSPEL", "content": "Elke speler dribbelt met een bal door het vak. De trainer gebruikt de vooraf aan\ngegeven tekens.\nBij het fluiten of het roepen van een nummer moeten de spelers de daarbij\nbehorende afgesproken tekens uitvoeren, zoals:\n- Naar de zijkant dribbelen\n- Een kapbeweging maken\n- De bal stil leggen onder de voet\n- Een versnelling maken met de bal aan de voet\n- De bal hooghouden.\n- Op de bal zitten\n- Wisselen van bal met een andere speler.\nOpgelet!\nMaak er een puntenspel van.\nWie behaalt de minste strafpunten?\nMaterialen\nTijd: 10-15 min\nRonde tijden: 1 a 2 min\nPylonen: 4 pylonen om het speelveld uit te zetten\nBallen: iedere speler heeft een bal."}, {"type": "techniek", "title": "STAP 2.2 C: AANBIEDEN, TOT 90º IN PLUSVORM (1)", "content": "A. Spelers 1 speelt naar speler 2.\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\nC. Speler 3 neemt de bal aan en dribbelt naar speler 4.\n- speler 3 sluit achter speler 4 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\n- idem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- idem, andersom met het andere been\nMaterialen\nAantal spelers: 8-10\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan lopen naar de volgende pylon.\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "AANBIEDEN, TOT 90º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: alle\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "OMSCHAKELING MET BAL (2)", "content": "Bij deze oefening wordt de omschakeling van voetballers getraind.\nDe spelers worden hierbij in 2 groepen van elk 6 spelers verdeeld. Eén groep is\nvoorzien van een hesje. Elke speler uit de ene groep vormt een tweetal met een\nspeler uit de andere groep.\nBij dit spel brengen de spelers van de ene groep de bal buiten de middencirkel\n(niet schieten). De andere spelers van elk tweetal uit de andere groep pakken de\nbal weer op en brengen deze weer naar de middencirkel.\nWelk tweetal heeft als eerste 5 ballen bij elkaar?\nOpgelet!\n- dit zijn introductievormen bij de looptraining.\nMaterialen\nAantal spelers: 12\nOrganisatie:\n- middencirkel.\nTEGENSTANDER VOOR JE: IN EEN Y-VORM\nMethodiek\nDe onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 maakt de beweging\n- Speler 1 voert de \"Aai-buitenkantvoet\" (Stap 5A) uit.\nC. Speler 1 dribbelt naar speler 2\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 2.\n- Speler 2 neemt de bal aan en voert nu dezelfde oefening, met\nhet andere been, uit.\nIdem voor de spelers 4,5 en 6.\nMaterialen\nAantal spelers: 6\nAantal ballen; 2\nAantal pylonen: 5\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening, met het andere\nbeen, in tegenovergestelde richting uit. Daarna\nneemt deze speler de plaats in van speler 3, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "AANVALLEN DOOR MIDDENVELDERS EN AANVALLERS (5 : 4+KEEPER) KLEIN VELD", "content": "D.w.z. dat 5 aanvallers/ middenvelders d.m.v. samenspel kansen\ncreëren.\nDe 4 verdedigers /middenvelders+ keeper kunnen scoren door de\nbal over de lijn van één van de kleine doetjes te dribbelen.\nDe aanvallers kunnen op het grote doel scoren.\nDe oefening start altijd bij de aanvallers.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nMiddenvelders/aanvallers bij aanvallen\ncoachen op:\n- het samenspelen vanuit een halve kom\n- het opkomen van de middenvelder\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (7+11)\n- het loskomen van de tegenstander d.m.v.\nvooracties.\n- het creëren van een twee tegen een situatie.\nMiddenvelders/aanvallers bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)\n- het direct druk zetten op de bal."}, {"type": "partijvorm", "title": "PARTIJVORM 5:5 (2)", "content": "Vijf aanvallers moeten d.m.v. samenspel/ individuele actie 5\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers: 10(15)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 30m bij 25m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-junioren: 5m bij 2m\nDoordraaien:\n- het winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\n- geen score na twee minuten, dan wordt de\nlangst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}]}'::jsonb),
('O10', 18, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VOOR JE: IN LIJNVORM (1)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 4)\n- Akka (buiten-binnen) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 E: AANBIEDEN, TOT 180º MET HET ZELFDE/ANDERE BEEN IN LIJNVORM", "content": "A. Speler 1 speelt de bal naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nlinker/rechtervoet aan.\nB. Speler 2 speelt de bal naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de\nrechter/linkervoet\n- speler 3 neemt de bal met de binnenkant van de\nlinker/rechtervoet aan, etc.\nVariatie in uitvoering:\n- idem, aannemen en spelen met het zelfde been.\nVariatie in aanbieden:\n- naar rechts\n- naar links\n- achterwaarts\nVariatie\nVariatie 3: Aanbieden voorwaarts, achterwaarts, rechts en links\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- wisselen naar eigen inzicht\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelend\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "(4 : 2) OEFENING 2", "content": "Vier aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe verdediger moet na het veroveren van de bal d.m.v. lijndribbel\nscoren over de korte zijden(omschakeling).\nDe aanvaller die de fout maakt wordt verdediger.\nWisselen van taak: De verdediger die het langst in het midden\nheeft gestaan wisselt met de aanvaller die de fout heeft gemaakt\nof hij wisselt met de langst staande aanvaller.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 12m bij 10m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "HIELAANSLAG-ESTAFETTE", "content": "Is een oefening, waarbij de speler(s) de stap van de onderstaande\ntechniek in voorwaartse richting uitvoert(en) tot bij de medespeler\naan de andere kant. Ondertussen voert hij daarbij de hielslag uit,\nterwijl hij de bal met een lichte hoek in de ellebogen in de handen\nvoor het lichaam houdt. Aan de overkant gekomen geeft hij de bal\nover en zijn medespeler voert vervolgens ook de oefening in\ntegengestelde richting uit.\n1. Hielaanslag (Stap 2)\nOpgelet!\nDit is een eindvorm. Deze vorm kan alleen worden uitgevoerd als\nde speler stap 2 van de hielaanslag beheerst.\nMaterialen\nAantal spelers: 10\nAantal ballen: 2\nAantal pylonen: 4\nOrganisatie:\nDe spelers( 3 aan de ene en 2 aan de andere\nkant) staan verdeeld in 2 rijen achter de op een\nonderlinge afstand van 15 mtr. geplaatste\npylonen tegenover elkaar.De voorste speler\nheeft een bal in de handen en start de oefening\nWinnaar is de rij die het eerst de oefening\nuitgevoerd heeft\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VOOR JE: IN EEN PLUSVORM (BINNEN)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet,\ninzet beweging binnenkant rechter voet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Sleep (Stap 4A)\n- Akka (binnen-voor) (Stap 3A)\n- Uitstappen/meenemen (Stap 5A)\n- Akka (binnen-buiten) (Stap 3A)\nC. Speler 1 dribbelt naar speler 2\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 2.\n- Speler 2 neemt de bal aan en voert nu dezelfde oefening, met\nhet andere been, uit.\nIdem voor de spelers 4,5 en 6.\nVariatie:\nEen dubbele schaarbeweging door 2x om de bal heen te bewegen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 6\nAantal ballen; 2\nAantal pylonen: 5\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening, met het andere\nbeen, in tegenovergestelde richting uit. Daarna\nneemt deze speler de plaats in van speler 3, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VOOR JE: IN EEN PLUSVORM (BUITEN)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 5A)\n- Akka (buiten-binnen) (Stap 3A)\nC. Speler 1 dribbelt naar speler 2\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 2.\n- Speler 2 neemt de bal aan en voert nu dezelfde oefening, met\nhet andere been, uit.\nIdem voor de spelers 4,5 en 6.\nVariatie:\nEen dubbele schaarbeweging door 2x om de bal heen te bewegen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 6\nAantal ballen; 2\nAantal pylonen: 5\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening, met het andere\nbeen, in tegenovergestelde richting uit. Daarna\nneemt deze speler de plaats in van speler 3, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VOOR JE: MET KAATSER (2)", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\nDribbelen buitenkant voet:\n- Schaar (Stap 5A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB.Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit.\nC. Daarna speelt hij de bal, voor een kaats, op speler 2 en loopt\ndoor om de bal te ontvangen.\nD. Vervolgens kaatst speler 2 de bal op de doorgelopen speler 1.\nE. Speler 1 controleert/werkt af op doel of werkt direct af op doel.\nF. Speler 2 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nAfstand kaatser vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 neemt de taak over van speler 2\n- Speler 2 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Juist inschatten van de snelheid van de bal\nom met je passen goed uit te komen, zodat\nje direct op doel kunt afwerken.\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Afhankelijk van de situatie met\nde binnenkant of met de volle wreef\n- Standbeen iets voorbij de bal dan blijft de\nbal laag.\n- Standbeen iets achter de bal en raak de bal\naan de onderkant, dan gaat de bal omhoog.\nPARTIJVORM 1:1\nMethodiek\nEén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}]}'::jsonb),
('O10', 19, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VOOR JE: IN LIJNVORM (2)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 4)\n- Sleep (Stap 3)\n- Akka (binnen-voor) (Stap 2)\n- Uitstappen meenemen (Stap 4)\n- Akka (binnen-buiten) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 D: INGOOIEN, AANBIEDEN, TOT 135º IN Y-VORM", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 gooit de bal in.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Spelers 3 dribbelt met de bal naar speler 8.\n- Speler 3 wisselt van kant ensluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nOpgelet!\nIdem aan de andere kant voor de spelers 5 t/m 8, alleen dan met\nlinks uitvoeren.\nVariatie in uitvoering:\nAannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nVariatie in aanbieden:\n- Naar rechts\n- Naar links\n- Achterwaarts\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nWisselen door in de andere rij aan te sluiten.\nAanwijzingen\nIngooi:\n- Beiden voeten houden contact met de\ngrond.\n- De bal achter het hoofd loslaten.\n- Beide handen op de bal houden.\n- Voeten in de richting van het gooien.\n- Op het juiste been ingooien.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "STAP 2.2 A: KOPPEN (RECHT) VANUIT EEN POSITIE OP DE KNIEËN", "content": "Oefening met 2-tallen, waarbij speler 1 staat en speler 2 op de\nknieën zit.\nA. Speler 1 speelt naar speler 2\n- speler 1 gooit de bal onderhands aan.\nB. Speler 2 speelt naar speler 1\n- speler 2 kopt de bal recht terug , etc.\nVariatie in uitvoering:\n- zittende speler speelt de bal met kracht terug op de staande\nspeler en eindigt daarbij languit met zijn buik op de grond.\nMaterialen\nAantal spelers: 2\nAantal ballen: per tweetal een bal\nOnderlinge afstand pylonen:\n1e jaars E-pupillen: 2 m\n2e jaars E-pupillen: 2 m\nDoordraaien:\n- wisselen van functie naar eigen inzicht\nAanwijzingen\n- bovenlichaam naar achteren, kin op de\nborst\n- armen voor je houden\n- juiste moment bovenlichaam naar voren en\narmen naar achter\n- bal raken met het voorhoofd\n- speler 2 krijgt de bal recht aangegooid en\nwordt daardoor gedwongen om de bal ook\nrecht terug te koppen.\nLIJNDRIBBEL 3:2 MET DOEL\nMethodiek\nd.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}], "session_b": [{"type": "test", "title": "SPEEDLADDER (2)", "content": "Is een oefening, waarbij de zijwaartse vormen worden aangeleerd\nin de speedladder. De oefening is opgebouwd van grove motoriek\nnaar de fijne motoriek. Dat wil zeggen binnen de looptraining, er\nwordt gewerkt van een skipping naar skipping 45 graden en\nvervolgens naar kort voetenwerk.\nStap 1a: Twee voetjes in het raam plaatsen. (re)\nStap 1b: Twee voetjes in het raam plaatsen. (li)\nStap 2a: Vier voetjes in het raam plaatsen. (re)\nStap 2b: Vier voetjes in het raam plaatsen. (li)\nStap 3a: Eén voetje in het raam plaatsen. (re) (kruispas)\nStap 3b: Eén voetje in het raam plaatsen. (li) (kruispas)\nDifferentiatie:\nVoor de kruispas in de speedladder twee voetjes in elk raam\nplaatsen.\nLet op!\nDeze vormen kunnen spelenderwijs worden aangeleerd.\nMaterialen\nAantal spelers: het gehele team.\nAantal speedladders:\nEén, bij voorkeur twee.\nAantal pylonnen:\nEén\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast."}, {"type": "techniek", "title": "TEGENSTANDER NAAST JE: IN EEN PLUSVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- De verandering (Stap 4A)\n- Kappen binnenkant (Stap 4A)\n- Kappen buitenkant voet (Stap 4A)\n- Kappen achter het standbeen (Stap 3A)\n- De Overstap (Stap 5A)\nC. Speler 1 dribbelt naar speler 2\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 2.\n- Speler 2 neemt de bal aan en voert nu dezelfde oefening uit.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 8-12\nAantal ballen: 4\nAantal pylonen: 5\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 geeft de bal aan speler 2 enz.\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER NAAST JE: MET KAATSER", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- De verandering (Stap 4A)\n- Kappen achter het standbeen (Stap 3A)\n- Kappen binnenkant voet (Stap 4A)\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB. Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit.\nC. Daarna speelt hij de bal, voor een kaats, op speler 2 en loopt\ndoor om de bal te ontvangen.\nD. Vervolgens kaatst speler 2 kaats de bal op de doorgelopen\nspeler 1.\nE. Speler 1 controleert/werkt af op doel of werkt direct af op doel.\nF. Speler 2 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nAfstand kaatser vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 neemt de taak over van speler 2\n- Speler 2 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Juist inschatten van de snelheid van de bal\nom met je passen goed uit te komen, zodat\nje direct op doel kunt afwerken.\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Afhankelijk van de situatie met\nde binnenkant of met de volle wreef\n- Standbeen iets voorbij de bal dan blijft de\nbal laag.\n- Standbeen iets achter de bal en raak de bal\naan de onderkant, dan gaat de bal omhoog."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in één van de twee aan de\nandere kant van het vak staande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw\nMaterialen\nAantal spelers: 8\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm.\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten."}]}'::jsonb),
('O10', 20, '{"session_a": [{"type": "warming_up", "title": "LIJNEN SPEL", "content": "De spelers staan met de bal aan de voet op een door de trainer\naangegeven lijn van het 16- meter gebied. Op zijn teken dribbelen\nde spelers naar een door de trainer aangegeven andere lijn.\nOpgelet!\nGeen 16- meter gebied beschikbaar, maak dan gebruik van\nverschillend gekleurde pylonen of hoedjes om daarmee lijnen te\nvormen\nMaak bij de\" jongste jeugd\" gebruik van nummers.\nVariatie:\n- Geef elke speler bij aanvang 3 punten en haal bij de laatste\ntelkens 1 punt af. Winnaar is ook nu weer degene die over blijft.\n- Laatste valt steeds af en winnaar is degene die over blijft (alleen\ndoen als afsluiting van een training).\nMaterialen\nAantal spelers: 4-14\nAantal pylonen: 10 (om eventueel de lijnen aan\nte geven)\nAantal ballen: elke speler 1 bal\nAanwijzingen\nSpelers coachen op:\n- Draai eerst proef.\n- De bal moet wel steeds op de lijn onder de\nvoet stil liggen."}, {"type": "techniek", "title": "STAP 2.2 C: AANBIEDEN, TOT 90º IN PLUSVORM (2)", "content": "A. Spelers 1 speelt naar speler 2.\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\nC. Speler 3 neemt de bal aan en dribbelt naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\n- idem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nMaterialen\nAantal spelers: 8-10\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan lopen naar de volgende pylon.\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "(4 : 2) OEFENING 1", "content": "Vier aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe aanvaller die een fout maakt wisselt van taak met de langst\nstaande verdediger.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 12m bij 10m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "RATTEN EN RAVEN", "content": "Het spel wordt gespeeld met tweetallen, die recht tegenover\nelkaar staan, op een onderlinge afstand van 2 meter. Aan de ene\nkant staan de ratten en aan andere kant de raven.\nAls verteller vertelt de trainer een verhaal waarin de woorden\nratten en raven steeds voorkomen. Op het moment dat de trainer\néén van deze namen noemt, dan moet die groep zo snel mogelijk\nnaar hun achterlijn zien te lopen.De andere groep moet hen zien\nte tikken voordat zij bij hun achterlijn zijn.\nJe krijgt voor elke getikte speler 1 punt.\nMaterialen\nDuur:10-15 min\nAantal: 4 of meer spelers\nPylonen:\n- 4 om het speelveld af te bakenen.\n- 4 pylonen/hoedjes om de vrije zone aan te\ngeven.\n- 4 pylonen/hoedjes om de startlijn aan te geven.\n- 2 pylonen/hoedjes op de middenlijn aan te\ngeven\nAanwijzingen\n- als de speler de ander voor de vrije zone\nkan tikken dan heeft die een punt. Speel een\npotje tot de vijf.\n- zorg dat de spelers ook echt starten\nwanneer hun naam genoemd wordt\n- probeer er een leuk verhaal van te maken.\nNiet alleen maar ratten en raven roepen, dus\nspelen met de ''rrrrr''."}, {"type": "techniek", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN EEN PLUSVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- 2x kappen buitenkant voet (Stap 4A)\n- Pirouette (Stap 6A)\n- Aai-kappen achter het standbeen (Stap 5A)\n- de Schijntrap (Stap 5A)\nC. Speler 1 dribbelt naar speler 2\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 2.\n- Speler 2 neemt de bal aan en voert nu, met het andere been, in\ntegengestelde richting dezelfde oefening uit.\n- Speler 2 geeft de bal aan speler 3, etc.\nIdem voor de spelers 4,5 en 6.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 6\nAantal ballen: 2\nAantal pylonen: 5\nOnderlinge afstand pylonen: 10 mtr. tot de\nmiddelste pylon\nDoordraaien:\n- Speler 1 geeft de bal aan speler 2. Deze speler\nvoert de oefening met het andere been in\ntegenovergestelde richting uit en geeft de bal\naan speler 3. Enz.\n- Idem voor de spelers 4,5 en 6.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "OPBOUW DOOR VERDEDIGERS EN MIDDENVELDER (5+KEEPER : 4) KLEIN VELD", "content": "D.w.z. dat 5 verdedigers / middenvelders + keeper d.m.v.\nsamenspel 4 aanvallers/ middenvelders uitspelen, om daarna te\nscoren door de bal over de lijn van een van de doeltjes te\ndribbelen.\nDe aanvallers kunnen de afgepakte bal scoren op het grote doel.\nDe opbouw start altijd bij de doelman.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nSpelers te kort! Zorg dan dat je opbouwende\npartij een speler meer heeft.\nAanwijzingen\nVerdedigers/middenvelders bij opbouw\ncoachen op:\n- het breed maken van het veld door de\nverdedigers. Wordt één van de verdedigers\nin gespeeld dan knijpt de ander naar binnen\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (2+5)\n- het diep weglopen, om ruimte te maken,\nvan de centrale middenvelder\n- het benutten van een overtalsituatie\nVerdedigers/middenvelders bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}, {"type": "partijvorm", "title": "PARTIJVORM 5:5 (2)", "content": "Vijf aanvallers moeten d.m.v. samenspel/ individuele actie 5\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers: 10(15)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 30m bij 25m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-junioren: 5m bij 2m\nDoordraaien:\n- het winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\n- geen score na twee minuten, dan wordt de\nlangst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}]}'::jsonb),
('O10', 21, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Pirouette (Stap 5)\n- Aai achter standbeen (Stap 4)\n- De Schijntrap (Stap 4)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 D: AANBIEDEN, TOT 135º (ZELFDE/ANDERE BEEN) IN RUITVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Speler 3 speelt naar speler 4\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, aannemen en spelen met het zelfde been.\nVariatie in aanbieden:\n- naar rechts\n- voorwaarts\n- achterwaarts\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "1. (3 : 1 + 2)", "content": "Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nWanneer de verdediger de bal onderschept dan moet hij de\nruimte zoeken met een lange pass naar het andere vak om\nzodoende het spel te verleggen.\nTevens gaan 1 verdediger en 1 aanvaller mee naar het andere\nveld. Nu moeten de drie verdedigers d.m.v. samenspel de bal in\nhun bezit zien te houden zonder dat de aanvaller de bal kan\nveroveren. Etc.\nVariatie in aanbieding:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 6\nAfstand tussen de pylonen: 2x (10m bij 8m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- omschakeling van balbezit naar balverlies\n- druk op de bal geven zodat de aanvallers\neen fout maken"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "STOKKENLOOP TIKKERTJE", "content": "Bij deze oefening staan de spelers verdeeld in 2 groepen van elk 6 spelers\ntegenover elkaar aan beide zijden van het “stokken-parcours”.\nAan het eind van beide parcoursen staan twee verschillend gekleurde pylonen\nmet aan weerszijden op 10 meter afstand daarvan nog een pylon.\nEr wordt tegelijkertijd gestart met het stokkenparcours(foutloos lopen, anders\nopnieuw).\nDe eerste aangekomene tikt een pylon aan en kiest vervolgens een richting.\nDe laatst aangekomene moet nadat hij de pylon heeft aangetikt de ander\nproberen in te halen en te tikken.\nLet op!\nBij beheersing van het stokkenparcours kan er op snelheid wordt gewerkt.\nMaterialen\nAantal spelers: 12\nAantal pylonen: 24\nOrganisatie:\nDe spelers staan tegenover elkaar met een ruimte er tussen van 20 á 25 meter.\nDe onderlinge afstanden van het stokkenparcours moet even groot zijn."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN EEN LIJNVORM", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de voet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan (deze doet alsof hij een speler in de rug heeft).\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Binnen-buitenkant wegdraai (Stap 4)\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\nC. Speler 1 dribbelt naar speler 6\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 6.\nIdem voor de spelers 4,5 en 6 in tegengestelde richting, etc.\nVariatie:\nIdem, maar nu met het andere been uitvoeren.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 6\nAantal ballen; 2\nAantal pylonen: 3\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt, na de pass op speler 2, diens\nplaats in. Speler 2 dribbelt naar speler 6 en geeft\nhem de bal. Speler 4 neemt, na de pass op\nspeler 5, diens plaats in en speler 5 geeft de bal\naan speler 3, etc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: MET KAATSER", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\n- Binnen-buitenkant wegdraai (Stap 4)\nA. Speler 1 start de oefening door de bal met de rechter\nbinnenkant van de voet op speler 2 te passen (deze doet alsof hij\neen speler in de rug heeft).\nB. Speler 2 ontvangt de bal en voert vervolgens één van de\nbovengenoemde technieken uit.\nC. Daarna speelt hij de bal, voor een kaats, op speler 3 en loopt\ndoor om de bal te ontvangen\nD. Vervolgens kaatst speler 3 de bal terug op de doorgelopen\nspeler 2.\nE. Speler 2 controleert/werkt af op doel of werkt direct af op doel.\nF. Speler 3 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nAfstand kaatser vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 loopt door naar de volgende pylon en\nneemt de positie over van speler 2.\n- Speler 2 neemt de taak over van speler 3\n- Speler 3 haalt de bal en sluit achter in de\nandere rij aan.\nIdem aan de andere kant\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Juist inschatten van de snelheid van de bal\nom met je passen goed uit te komen, zodat\nje direct op doel kunt afwerken.\nBal in het hart raken\n- Spanning in de voet\n- Raakvlak: Afhankelijk van de situatie met\nde binnenkant of met de volle wreef\n- Standbeen iets voorbij de bal dan blijft de\nbal laag.\n- Standbeen iets achter de bal en raak de bal\naan de onderkant, dan gaat de bal omhoog."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}]}'::jsonb),
('O10', 22, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER NAAST JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- De verandering (Stap 3)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 C: INGOOIEN, AANBIEDEN, TOT 90º IN VIERKANT/STROOMVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 gooit de bal in\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 pakt de bal op.\nC. Speler 3 speelt naar speler 4\n- idem als beschreven bij A.\nD. Speler 4 speelt naar speler 5\n- idem als beschreven bij B, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been\n- idem, met rechts aannemen en met links spelen.\nVariatie in aanbieden:\n- Naar rechts\n- Achterwaarts\n- Voorwaarts\nMaterialen\nAantal spelers: 5-7\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nIngooi:\n- beide voeten houden contact met de grond\n- de bal achter het hoofd loslaten\n- beide handen op de bal houden\n- voeten in de richting van het gooien\n- op het juiste been ingooien.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "STAP 2.2 B: KOPPEN (SCHUIN) VANUIT EEN POSITIE OP DE KNIEËN", "content": "Oefening met 2-tallen, waarbij speler 1 schuin t.o.v. speler 2 staat\nen speler 2 op de knieën zit.\nA. Speler 1 speelt naar speler 2\n- speler 1 gooit de bal onderhands aan.\nB. Speler 2 speelt naar speler 1\n- speler 2 kopt de bal schuin terug , etc.\nVariatie in uitvoering:\n- idem, maar nu de aangooi vanaf de andere kant.\nMaterialen\nAantal spelers: 2\nAantal ballen: per tweetal een bal\nOnderlinge afstand pylonen:\n- 1e jaars E-pupillen: 2 m\n- 2e jaars E-pupillen: 2 m\nDoordraaien:\n- wisselen van functie naar eigen inzicht\nAanwijzingen\n- bovenlichaam naar achteren, kin op de\nborst\n- armen voor je houden\n- juiste moment bovenlichaam naar voren en\narmen naar achter\n- bal raken met het voorhoofd\n- speler 2 krijgt de bal schuin aangegooid en\nwordt daardoor gedwongen om de bal ook\nschuin terug te koppen.\nLIJNDRIBBEL 3:2 MET DOEL\nMethodiek\nd.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}], "session_b": [{"type": "warming_up", "title": "TENNISBALLENSPEL", "content": "Bij deze oefening wordt het ‘omschakelmoment’ van een speler\naangeleerd en getraind. Door deze oefening wordt een speler\nhandig in het lichtvoetig draaien. Tevens benadrukt deze oefening\nhet ‘laag zitten’ bij het wegdraaien bij de speler.\nOrganisatieuitleg:\nEr zijn bij het spel 4 pylonnen, 4 tennisballen en één hoepel\naanwezig. De pylonnen staan in een plusvorm en op de pylonnen\nliggen de tennisballen.\nSpeluitleg:\nDe speler begint in de hoepel, op een commando van de trainer\nstart de speler naar de eerste pylon. De speler pakt de tennisbal\nmet de rechterhand en geeft de bal over in zijn linkerhand en legt\nhem vervolgens in de hoepel. Vanuit de hoepel vertrekt de zelfde\nspeler naar de tweede pylon en pakt tevens weer een tennisbal\nvan de tweede pylon met zijn rechterhand, geeft deze weer over\nnaar zijn linkerhand en legt vervolgens de tennisbal weer in de\nhoepel. De speler vervolgt de zelfde volgorde ook bij de derde en\nvierde pylon.\nDifferentiatie:\nBiedt de vorm ook aan in een wedstrijdvorm, zodat de oefening\nook op maximale snelheid uitgevoerd moet worden.\nMaterialen\nAantal spelers: het gehele team.\nAantal organisaties:\nZoveel als mogelijk.\nAantal pylonnen voor één organisatie: 4\npylonnen.\nAantal hoepels voor één organisatie:\n1 hoepel\nOrganisatie:\nPer situatie voert één speler de oefening uit.\nAanwijzingen\nLet op!\nZorg ervoor dat de oefening volledig wordt\nuitgevoerd. Dat de speler tevens bij elke\nomschakeling ‘laag zit’ (gebogen knieën\nheeft)."}, {"type": "techniek", "title": "A. TEGENSTANDER VOOR JE: IN EEN RECHTHOEKVORM (BUITEN)", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 dribbelt richting middelste pylonen\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 maakt de beweging\n- Schaar (Stap 5A)\n- Akka (buiten-binnen) (Stap 3A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken Schaar (Stap 5A) en\nAkka (buiten-binnen) (Stap 3A).\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening, met het andere\nbeen, in tegenovergestelde richting uit. Daarna\nneemt deze speler de plaats in van speler 2, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- Het moment waarop je de beweging inzet is\nafhankelijk van de snelheid van het dribbelen\n(eerder of later inzetten).\n- Je mag de tegenstander, bij de uitvoering\nvan de oefening, niet raken."}, {"type": "techniek", "title": "TEGENSTANDER VOOR JE: MET WEERSTAND (2)", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\nDribbelen buitenkant voet:\n- Schaar (Stap 5B)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB. Ter hoogte daarvan komt een tegenstander (speler 2) frontaal\nop hem inlopen. Hij passeert vervolgens de tegenstander met één\nvan de bovengenoemde technieken.\nC. Daarna controleert hij de bal en rond vervolgens af op het doel\nD. Speler 2 haalt de bal en sluit achter in de andere rij aan en\nspeler 1 neemt de taak over van speler 2.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 2 haalt de bal en sluit achter in de\nandere rij aan.\n- Speler 1 neemt de taak over van speler 2.\n- Idem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O10', 23, '{"session_a": [{"type": "warming_up", "title": "KRISKRASORGANISATIE (1)", "content": "Spelers voeren één van de stappen van de onderstaande\ntechnieken uit, terwijl zij met de bal aan de voet , zonder elkaar te\nhinderen, door het hele vak bewegen.\n- Schaar en Pirouette (Stap 2)\n- Sleep (Stap 1)\n- Uitstappen/meenemen (Stap 2)\n- De Overstap (Stap 2)\n- De Schijntrap (Stap 2)\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 1-8\nAantal ballen: elke speler 1 bal\nAantal pylonen: 4\nDe pylonen vormen een rechthoek van 10 bij 8\nmtr.\nOrganisatie:\nSpelers staan kris kras door elkaar.\nDe trainer geeft eerst een beeld van de oefening\nen controleert daarna de uitvoering.\nAanwijzingen\nVoor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 D: AANBIEDEN, TOT 135º IN X-VORM", "content": "A. Speler 1 speelt naar speler 2.\n- speler 2 biedt zich \"voorwaarts\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Spelers 3 dribbelt met de bal naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nVariatie in uitvoering:\n- idem, andersom oefening met links uitvoeren\n- aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nVariatie in aanbieden:\n- naar rechts\n- naar links\n- achterwaarts\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "(4 : 2) OEFENING 2", "content": "Vier aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe verdediger moet na het veroveren van de bal d.m.v. lijndribbel\nscoren over de korte zijden(omschakeling).\nDe aanvaller die de fout maakt wordt verdediger.\nWisselen van taak: De verdediger die het langst in het midden\nheeft gestaan wisselt met de aanvaller die de fout heeft gemaakt\nof hij wisselt met de langst staande aanvaller.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 12m bij 10m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in één van de twee aan de\nandere kant van het vak staande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw\nMaterialen\nAantal spelers: 8\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm.\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten."}], "session_b": [{"type": "warming_up", "title": "STOKKENLOOP (1)", "content": "Is een oefening, waarbij de voorwaartse vormen worden\naangeleerd over de stokken. De oefening is opgebouwd van grove\nmotoriek naar de fijne motoriek. Dat wil zeggen binnen de\nlooptraining, er wordt gewerkt van een skipping naar skipping 45\ngraden en vervolgens naar kort voetenwerk.\nEr moet hierbij wel nadrukkelijk worden gelet op het lichtvoetig\nagreren over de stokken. Dat wil zeggen dat alles met de bal van\nde voet wordt uitgevoerd. Ten allen tijden wordt er op de bal van\nde voet gelopen.\nStap 1: Er wordt met de rechtervoet begonnen. De eerste stok\nwordt voorwaarts genomen en vervolgens wordt er met twee\nvoeten teruggestapt, de andere stokken worden gelopen met één\nvoet tussen de stokken.\nStap 2: Er wordt met de rechtervoet begonnen. De eerste en de\nderde stok worden voorwaarts genomen en vervolgens wordt er\nmet twee voeten teruggestapt, de andere stokken worden\ngelopen met één voet tussen de stokken.\nStap 3: Er wordt met de rechtervoet begonnen. De eerste, de\nderde en de vijfde stok worden voorwaarts genomen en\nvervolgens wordt er met twee voeten teruggestapt, de andere\nstokken worden gelopen met één voet tussen de stokken.\nDifferentiatie:\nLet op!\nDe romphouding moet recht zijn en er moet een duidelijke\narminzet aanwezig zijn.\nMaterialen\nAantal spelers: het gehele team.\nAantal stokkenparcours:\nEén, bij voorkeur twee.\nAantal pylonnen:\n12\nAantal stokken:\n5\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast."}, {"type": "techniek", "title": "B. TEGENSTANDER VOOR JE: IN EEN RECHTHOEKVORM (BINNEN)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet,\ninzet beweging binnenkant rechter voet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 5A)\n- Sleep (Stap 4A)\n- Akka (binnen-voor) (Stap 3A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nVariatie:\nEen dubbele schaarbeweging door 2x met de voet om de bal heen\nte bewegen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Aai buitenkant voet\n(Stap 5A), Sleep (Stap 4A) en Akka (binnen-voor) (Stap 3A).\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening, met het andere\nbeen, in tegenovergestelde richting uit. Daarna\nneemt deze speler de plaats in van speler 2, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "AANVALLEN DOOR MIDDENVELDERS EN AANVALLERS (5 : 4+KEEPER) KLEIN VELD", "content": "D.w.z. dat 5 aanvallers/ middenvelders d.m.v. samenspel kansen\ncreëren.\nDe 4 verdedigers /middenvelders+ keeper kunnen scoren door de\nbal over de lijn van één van de kleine doetjes te dribbelen.\nDe aanvallers kunnen op het grote doel scoren.\nDe oefening start altijd bij de aanvallers.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nMiddenvelders/aanvallers bij aanvallen\ncoachen op:\n- het samenspelen vanuit een halve kom\n- het opkomen van de middenvelder\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (7+11)\n- het loskomen van de tegenstander d.m.v.\nvooracties.\n- het creëren van een twee tegen een situatie.\nMiddenvelders/aanvallers bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)\n- het direct druk zetten op de bal."}, {"type": "partijvorm", "title": "PARTIJVORM 5:5 (2)", "content": "Vijf aanvallers moeten d.m.v. samenspel/ individuele actie 5\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers: 10(15)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 30m bij 25m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-junioren: 5m bij 2m\nDoordraaien:\n- het winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\n- geen score na twee minuten, dan wordt de\nlangst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}]}'::jsonb),
('O10', 24, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER ACHTER JE: IN LIJNVORM HEEN TERUG", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt naar overstaande pylon.\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Kappen buitenkant voet (Stap 3)\n- Binnen-buitenkant wegdraai (Stap 3)\n- De Overstap (Stap 4)\nC. Speler dribbelt terug en herhaald stap B bij de pylon.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.2 C: AANBIEDEN, TOT 90º IN VIERKANTVORM", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\"aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\nC. Speler 3 speelt naar speler 4\n- Speler 4 biedt zich \"naar links\"aan.\n- Speler 3 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 4.\nD. Speler 4 speelt naar speler 1\n- Idem als beschreven bij B, etc.\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nVariatie\nVariatie 3: Aanbieden voorwaarts, achterwaarts, rechts en links\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Laag zitten (goed door de knieën).\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "LIJNDRIBBEL 2:1 MET DOEL", "content": "d.w.z. dat 2 aanvallers d.m.v. samenspel/ een persoonlijke actie\neen verdediger uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 2 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdediger kan de afgepakte bal scoren door de bal over de\nlijn aan de overkant te dribbelen.\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen:\nF-pupillen: 15m bij 10m\nE-pupillen: 18m bij 12m\nD-pupillen: 20m bij 15m\nC-,B-,A-junioren: 25m bij 20m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- keuzes maken aan de bal( 1:1 of overspelen)\n- rekening houden, bij het innemen van een\naanvallende positie, met de omschakeling bij\nbalverlies(restverdediging)\nVerdediger coachen op:\n- rekening houden met een goed zicht op de\npositie van de beide aanvallers bij het\ninnemen van een verdedigende positie(open\nstaan)\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "SPIEGELEN (2)", "content": "Oefeningen, waarbij de speler(s) de door de tegenstander\nuitgevoerde stappen van de onderstaande technieken, in voor-,\nachter-, zijwaartse richting, nadoet(n).\n1. Tripling (Stap 3, 4)\n2. Skipping (Stap 4)\n3. Hielaanslag (Stap 2)\nOpgelet!\n- alleen uitvoeren als de spelers bekend zijn met bovenstaande\ntechnieken.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 2\nDe pylonen vormen een rechte lijn van 2 mtr.\nOrganisatie:\n- de spelers staan hierbij recht tegenover één\nspeler die de leiding heeft. Zij moeten daarbij\nzijn bewegingen volgen (spiegelen).\nAanwijzingen\n- Voor de beschrijving van de techniek, zie\ntechnieklijst."}, {"type": "techniek", "title": "A. TEGENSTANDER NAAST JE: IN EEN RECHTHOEKVORM", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 dribbelt richting middelste pylonen\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 maakt de beweging\n- De verandering (Stap 4A)\n- De Overstap (Stap 5A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nLet op! Bij een inzet met de linkervoet over de bal, moet men ook\nmet links dribbelen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken De verandering (Stap\n4A) en De Overstap (Stap 5A).\nMaterialen\nAantal spelers: 3-5\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening in\ntegenovergestelde richting uit en passed de bal\nop zijn beurt weer op speler 3, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER NAAST JE: MET KAATSER", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- De verandering (Stap 4A)\n- Kappen achter het standbeen (Stap 3A)\n- Kappen binnenkant voet (Stap 4A)\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB. Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit.\nC. Daarna speelt hij de bal, voor een kaats, op speler 2 en loopt\ndoor om de bal te ontvangen.\nD. Vervolgens kaatst speler 2 kaats de bal op de doorgelopen\nspeler 1.\nE. Speler 1 controleert/werkt af op doel of werkt direct af op doel.\nF. Speler 2 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nAfstand kaatser vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 neemt de taak over van speler 2\n- Speler 2 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Juist inschatten van de snelheid van de bal\nom met je passen goed uit te komen, zodat\nje direct op doel kunt afwerken.\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Afhankelijk van de situatie met\nde binnenkant of met de volle wreef\n- Standbeen iets voorbij de bal dan blijft de\nbal laag.\n- Standbeen iets achter de bal en raak de bal\naan de onderkant, dan gaat de bal omhoog."}, {"type": "partijvorm", "title": "PARTIJVORM 1:1", "content": "Eén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}]}'::jsonb),
('O10', 25, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VOOR JE: IN LIJNVORM (1)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 4)\n- Akka (buiten-binnen) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 D: INGOOIEN, AANBIEDEN, TOT 135º IN RUIT/STROOMVORM", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar rechts\" aan.\n- Speler 1 gooit de bal in.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 pakt de bal op.\nC. Speler 3 speelt naar speler 4\n- Idem als beschreven bij A.\nD. Speler 4 speelt naar speler 5\n- Idem als beschreven bij B, etc.\nVariatie in uitvoering:\n- Idem, met rechts aannemen en met links spelen.\n- Idem, andersom met het andere been.\nVariatie in aanbieden:\n- Naar links\n- Voorwaarts\n- Achterwaarts\nMaterialen\nAantal spelers: 5-7\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nIngooi:\n- Beiden voeten houden contact met de\ngrond.\n- De bal achter het hoofd loslaten.\n- Beide handen op de bal houden.\n- Voeten in de richting van het gooien.\n- Op het juiste been ingooien.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "STAP 2.2 B: KOPPEN (SCHUIN) VANUIT EEN POSITIE OP DE KNIEËN", "content": "Oefening met 2-tallen, waarbij speler 1 schuin t.o.v. speler 2 staat\nen speler 2 op de knieën zit.\nA. Speler 1 speelt naar speler 2\n- speler 1 gooit de bal onderhands aan.\nB. Speler 2 speelt naar speler 1\n- speler 2 kopt de bal schuin terug , etc.\nVariatie in uitvoering:\n- idem, maar nu de aangooi vanaf de andere kant.\nMaterialen\nAantal spelers: 2\nAantal ballen: per tweetal een bal\nOnderlinge afstand pylonen:\n- 1e jaars E-pupillen: 2 m\n- 2e jaars E-pupillen: 2 m\nDoordraaien:\n- wisselen van functie naar eigen inzicht\nAanwijzingen\n- bovenlichaam naar achteren, kin op de\nborst\n- armen voor je houden\n- juiste moment bovenlichaam naar voren en\narmen naar achter\n- bal raken met het voorhoofd\n- speler 2 krijgt de bal schuin aangegooid en\nwordt daardoor gedwongen om de bal ook\nschuin terug te koppen."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "warming_up", "title": "KOE KOPEN", "content": "Oefening(en), waarbij de speler(s) voor elkaar staan met hun gezicht in de\nrichting van de finishlijn. De voorste speler geeft een tik op de hand van de\nspeler die achter hem staat en loopt vervolgens weg. De tik is het teken waarop\nde achterste speler de voorste speler mag proberen te tikken, voordat deze\nspeler de finishlijn heeft gepasseerd.\nOpgelet!\n- het is een reactiespel, waarbij de jongste jeugd spelenderwijs het spel wordt\naangeleerd.\n- later, bij de oudere jeugd, kan daar goed gebruik van worden gemaakt.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 4\nDe pylonen vormen een rechte lijn van 2 mtr.\nOrganisatie:\n- bij dit spel staan de spelers recht tegenover één speler die de leiding heeft.\nDeze speler bepaalt wanneer het spel begint."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN EEN RECHTHOEKVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de voet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan (deze doet alsof hij een speler in de rug heeft).\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Binnen-buitenkant wegdraai (Stap 4)\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\nC. Speler 1 dribbelt naar speler 3\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 3.\n- Speler 1 geeft de bal aan speler 3, etc.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken De Overstap (Stap 5A),\nKappen buitenkant voet (Stap 4A) en Binnen buiten wegdraai\n(Stap 4).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt, na de pass op speler 2, diens\nplaats in. Speler 2 dribbelt naar de plek ter\nhoogte van de overstaande pylonen en geeft\ndaar de bal aan speler 3. Deze speler start de\noefening opnieuw, maar nu in tegengestelde\nrichting, door de bal op de doorgelopen speler 1\nte spelen, etc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: MET KAATSER", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\n- Binnen-buitenkant wegdraai (Stap 4)\nA. Speler 1 start de oefening door de bal met de rechter\nbinnenkant van de voet op speler 2 te passen (deze doet alsof hij\neen speler in de rug heeft).\nB. Speler 2 ontvangt de bal en voert vervolgens één van de\nbovengenoemde technieken uit.\nC. Daarna speelt hij de bal, voor een kaats, op speler 3 en loopt\ndoor om de bal te ontvangen\nD. Vervolgens kaatst speler 3 de bal terug op de doorgelopen\nspeler 2.\nE. Speler 2 controleert/werkt af op doel of werkt direct af op doel.\nF. Speler 3 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nAfstand kaatser vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 loopt door naar de volgende pylon en\nneemt de positie over van speler 2.\n- Speler 2 neemt de taak over van speler 3\n- Speler 3 haalt de bal en sluit achter in de\nandere rij aan.\nIdem aan de andere kant\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Juist inschatten van de snelheid van de bal\nom met je passen goed uit te komen, zodat\nje direct op doel kunt afwerken.\nBal in het hart raken\n- Spanning in de voet\n- Raakvlak: Afhankelijk van de situatie met\nde binnenkant of met de volle wreef\n- Standbeen iets voorbij de bal dan blijft de\nbal laag.\n- Standbeen iets achter de bal en raak de bal\naan de onderkant, dan gaat de bal omhoog."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O10', 26, '{"session_a": [{"type": "warming_up", "title": "PAALTJES VOETBAL 1", "content": "Het spel wordt gespeeld met 1 bal en elke speler start met 3\npunten. Alle spelers krijgen ergens in het vak een pylon te\nverdedigen. De spelers moeten proberen de pylon van elkaar\nomver te schieten. Gebeurt dit dan gaat er bij de desbetreffende\nspeler een punt af . Uiteindelijk blijft er 1 speler, de winnaar, over.\nVariatie:\nEen tweede bal in het spel brengen.\nOpgelet!\nBlijf niet voor je pylon hangen!\nMaterialen\nDuur:10-15 min\nAantal: 4 of meer spelers\nPylon: voor iedere speler 1\nBallen: 1-2\nAanwijzingen\nAls een speler geen punten meer heeft dan\ngaat hij aan de kant staan.\nSTAP 1: PARCOURS DRIBBELEN\nMethodiek\nDe spelers slalommen dribbelend het hele parcours door.\nVariatie in aanbieden:\n- varieer in uitvoeringssnelheid\n- varieer onderlinge afstand pylonen\n- voer de oefening in wedstrijdvorm uit.\nVariatie\nVariatie 4: Parcours dribbelen met zowel rechter als linker voet.\nMaterialen\nAantal spelers: 4-10\nAantal ballen: elke speler 1 bal\nAantal pylonen: 8\nOnderlinge afstand pylonen: 2 a 3 meter\nAanwijzingen\nSpelers coachen op:\n- houd de bal dichtbij je, maar niet onder je\n- probeer de bal zoveel mogelijk te raken\n- probeer de bal bij iedere stap te raken, dan\nkun je de bal ook beter sturen."}, {"type": "techniek", "title": "PARCOURS DRIBBELEN EN AFWERKEN", "content": "De spelers slalommen dribbelend het hele parcours door en werk\naf op doel.\nVariatie in aanbieden:\n- Varieer in uitvoeringssnelheid\n- Varieer onderlinge afstand pylonen.\n- Voer de oefening in wedstrijdvorm uit.\nMaterialen\nAantal spelers: 4-10\nAantal ballen: elke speler 1 bal\nAantal pylonen: 8\nDoelen: 2\nOnderlinge afstand pylonen: 2 a 3 meter\nAanwijzingen\nSpelers coachen op:\n- Houdt de bal dichtbij je, maar niet onder je.\n- Probeer de bal zoveel mogelijk te raken.\n- Probeer de bal bij iedere stap te raken, dan\nkun je de bal ook beter sturen."}, {"type": "partijvorm", "title": "PARTIJVORM 5:5 (2)", "content": "Vijf aanvallers moeten d.m.v. samenspel/ individuele actie 5\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers: 10(15)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 30m bij 25m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-junioren: 5m bij 2m\nDoordraaien:\n- het winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\n- geen score na twee minuten, dan wordt de\nlangst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "OMSCHAKELING MET BAL (2)", "content": "Bij deze oefening wordt de omschakeling van voetballers getraind.\nDe spelers worden hierbij in 2 groepen van elk 6 spelers verdeeld. Eén groep is\nvoorzien van een hesje. Elke speler uit de ene groep vormt een tweetal met een\nspeler uit de andere groep.\nBij dit spel brengen de spelers van de ene groep de bal buiten de middencirkel\n(niet schieten). De andere spelers van elk tweetal uit de andere groep pakken de\nbal weer op en brengen deze weer naar de middencirkel.\nWelk tweetal heeft als eerste 5 ballen bij elkaar?\nOpgelet!\n- dit zijn introductievormen bij de looptraining.\nMaterialen\nAantal spelers: 12\nOrganisatie:\n- middencirkel."}, {"type": "techniek", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN EEN RECHTHOEKVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Kappen buitenkant voet (Stap 4A)\n- Pirouette (Stap 6A)\n- Aai achter standbeen (Stap 5A)\n- De Schijntrap (Stap 5A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan en voert nu, met het andere been, in tegengestelde richting\ndezelfde oefening uit.\n- Speler 2 geeft de bal aan speler 3, etc.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 5: Het oefenen van de technieken Aai kappen achter\nstandbeen (Stap 5A), Kappen buitenkant voet (Stap 4A), Pirouette\n(Stap 6A) en De schijntrap (Stap 5A).\nMaterialen\nAantal spelers: 3-5\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 passed de bal op speler 2. Deze speler\nvoert de oefening in de tegenovergestelde\nrichting met het andere been uit en passed de\nbal op speler 3. Enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "OPBOUW DOOR VERDEDIGERS EN MIDDENVELDER (5+KEEPER : 4) KLEIN VELD", "content": "D.w.z. dat 5 verdedigers / middenvelders + keeper d.m.v.\nsamenspel 4 aanvallers/ middenvelders uitspelen, om daarna te\nscoren door de bal over de lijn van een van de doeltjes te\ndribbelen.\nDe aanvallers kunnen de afgepakte bal scoren op het grote doel.\nDe opbouw start altijd bij de doelman.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nSpelers te kort! Zorg dan dat je opbouwende\npartij een speler meer heeft.\nAanwijzingen\nVerdedigers/middenvelders bij opbouw\ncoachen op:\n- het breed maken van het veld door de\nverdedigers. Wordt één van de verdedigers\nin gespeeld dan knijpt de ander naar binnen\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (2+5)\n- het diep weglopen, om ruimte te maken,\nvan de centrale middenvelder\n- het benutten van een overtalsituatie\nVerdedigers/middenvelders bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}, {"type": "partijvorm", "title": "PARTIJVORM 5:5 (2)", "content": "Vijf aanvallers moeten d.m.v. samenspel/ individuele actie 5\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers: 10(15)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 30m bij 25m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-junioren: 5m bij 2m\nDoordraaien:\n- het winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\n- geen score na twee minuten, dan wordt de\nlangst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}]}'::jsonb),
('O10', 27, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VOOR JE: IN LIJNVORM (2)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 4)\n- Sleep (Stap 3)\n- Akka (binnen-voor) (Stap 2)\n- Uitstappen meenemen (Stap 4)\n- Akka (binnen-buiten) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.2 C: AANBIEDEN, TOT 90º IN PLUSVORM (2)", "content": "A. Spelers 1 speelt naar speler 2.\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\nC. Speler 3 neemt de bal aan en dribbelt naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\n- idem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nMaterialen\nAantal spelers: 8-10\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan lopen naar de volgende pylon.\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "(4 : 2) OEFENING 3", "content": "Vier aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe verdedigers moeten na het veroveren van de bal op de kleine\ndoeltjes scoren (omschakeling).\nWisselen van taak:De verdediger die het langst in het midden\nheeft gestaan wisselt met de aanvaller die de fout heeft gemaakt\nof hij wisselt met de langst staande aanvaller.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 12m bij 10m\nKleine doelen: 2x (3m bij 1m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "test", "title": "SPEEDLADDER (2)", "content": "Is een oefening, waarbij de zijwaartse vormen worden aangeleerd\nin de speedladder. De oefening is opgebouwd van grove motoriek\nnaar de fijne motoriek. Dat wil zeggen binnen de looptraining, er\nwordt gewerkt van een skipping naar skipping 45 graden en\nvervolgens naar kort voetenwerk.\nStap 1a: Twee voetjes in het raam plaatsen. (re)\nStap 1b: Twee voetjes in het raam plaatsen. (li)\nStap 2a: Vier voetjes in het raam plaatsen. (re)\nStap 2b: Vier voetjes in het raam plaatsen. (li)\nStap 3a: Eén voetje in het raam plaatsen. (re) (kruispas)\nStap 3b: Eén voetje in het raam plaatsen. (li) (kruispas)\nDifferentiatie:\nVoor de kruispas in de speedladder twee voetjes in elk raam\nplaatsen.\nLet op!\nDeze vormen kunnen spelenderwijs worden aangeleerd.\nMaterialen\nAantal spelers: het gehele team.\nAantal speedladders:\nEén, bij voorkeur twee.\nAantal pylonnen:\nEén\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast."}, {"type": "techniek", "title": "B. TEGENSTANDER VOOR JE: IN EEN RECHTHOEKVORM (BINNEN)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet,\ninzet beweging binnenkant rechter voet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 5A)\n- Sleep (Stap 4A)\n- Akka (binnen-voor) (Stap 3A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nVariatie:\nEen dubbele schaarbeweging door 2x met de voet om de bal heen\nte bewegen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Aai buitenkant voet\n(Stap 5A), Sleep (Stap 4A) en Akka (binnen-voor) (Stap 3A).\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening, met het andere\nbeen, in tegenovergestelde richting uit. Daarna\nneemt deze speler de plaats in van speler 2, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER NAAST JE: MET KAATSER", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- De verandering (Stap 4A)\n- Kappen achter het standbeen (Stap 3A)\n- Kappen binnenkant voet (Stap 4A)\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB. Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit.\nC. Daarna speelt hij de bal, voor een kaats, op speler 2 en loopt\ndoor om de bal te ontvangen.\nD. Vervolgens kaatst speler 2 kaats de bal op de doorgelopen\nspeler 1.\nE. Speler 1 controleert/werkt af op doel of werkt direct af op doel.\nF. Speler 2 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nAfstand kaatser vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 neemt de taak over van speler 2\n- Speler 2 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Juist inschatten van de snelheid van de bal\nom met je passen goed uit te komen, zodat\nje direct op doel kunt afwerken.\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Afhankelijk van de situatie met\nde binnenkant of met de volle wreef\n- Standbeen iets voorbij de bal dan blijft de\nbal laag.\n- Standbeen iets achter de bal en raak de bal\naan de onderkant, dan gaat de bal omhoog."}, {"type": "partijvorm", "title": "PARTIJVORM 1:1", "content": "Eén aanvaller moet 1 verdediger met een individuele actie\nuitspelen, om daarna in het doeltje aan de andere kant van het\nvak te scoren.\nDe verdediger kan de afgepakte bal aan de andere kant te scoren.\nMaterialen\nAantal spelers: 2\nAantal ballen: 3\nAantal pylonen: 4-8\nAfstand tussen pylonen:\nF-pupillen: 12m bij 8m\nE-pupillen: 15m bij 10m\nD-pupillen: 18m bij 12m\nC-junioren: 20m bij 15m\nB-,A-junioren: 25m bij 20m\nDoel: 2 ( 2 mtr.)\nAanwijzingen\nAanvaller coachen op:\n- het acties maken om zowel links als rechts\ner voorbij te gaan (duel)\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nVerdediger coachen op:\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het zoeken van het juiste moment om de\nbal te veroveren.\n- het in de gaten houden van zowel het doel\nals de tegenstander."}]}'::jsonb),
('O10', 28, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Pirouette (Stap 5)\n- Aai achter standbeen (Stap 4)\n- De Schijntrap (Stap 4)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 D: INGOOIEN, AANBIEDEN, TOT 135º IN Y-VORM", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 gooit de bal in.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Spelers 3 dribbelt met de bal naar speler 8.\n- Speler 3 wisselt van kant ensluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nOpgelet!\nIdem aan de andere kant voor de spelers 5 t/m 8, alleen dan met\nlinks uitvoeren.\nVariatie in uitvoering:\nAannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nVariatie in aanbieden:\n- Naar rechts\n- Naar links\n- Achterwaarts\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nWisselen door in de andere rij aan te sluiten.\nAanwijzingen\nIngooi:\n- Beiden voeten houden contact met de\ngrond.\n- De bal achter het hoofd loslaten.\n- Beide handen op de bal houden.\n- Voeten in de richting van het gooien.\n- Op het juiste been ingooien.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "STAP 2.2 C: DOORKOPPEN VANUIT EEN POSITIE OP DE KNIEËN", "content": "Oefening met 3-tallen, waarbij de aangooiende/ ontvangende\nspelers 1 en 3 een staande positie innemen en speler 2 op de\nknieën zit.\nA. Speler 1 speelt naar speler 2\n- speler 1 gooit de bal onderhands aan.\nB. Speler 2 speelt naar speler 3\n- speler 2 kopt de bal schuin door , etc.\nVariatie in uitvoering:\n- idem in tegengestelde richting, met een aangooi vanaf de\nandere kant.\nMaterialen\nAantal spelers: 3\nAantal ballen: per drietal een bal\nAfstand van pylonen:\n1e jaars E-pupillen: 2 m\n2e jaars E-pupillen: 2 m\nDoordraaien:\n- wisselen van functie naar eigen inzicht\nAanwijzingen\n- bovenlichaam naar achteren, kin op de\nborst .\n- armen voor je houden.\n- juiste moment bovenlichaam naar voren en\narmen naar achter.\n- bal raken met het voorhoofd.\n- de bal goed richting geven, door de\nduwbeweging in de richting van speler 3 te\nmaken."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in één van de twee aan de\nandere kant van het vak staande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw\nMaterialen\nAantal spelers: 8\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm.\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten."}], "session_b": [{"type": "warming_up", "title": "RATTEN EN RAVEN MET BAL", "content": "Het spel wordt gespeeld met tweetallen, die recht tegenover\nelkaar staan op een onderlinge afstand van 2 meter. Elke speler\nheeft een bal.\nAan de ene kant staan de ratten en aan andere kant de raven.\nAls verteller vertelt de trainer een verhaal waarin de woorden\nratten en raven steeds voorkomen. Op het moment dat de trainer\neen van deze namen noemt, dan moet die groep zo snel mogelijk\nnaar hun achterlijn zien te lopen.De andere groep moet hen zien\nte tikken voordat zij bij hun achterlijn zijn.\nJe krijgt voor elke getikte speler 1 punt.\nMaterialen\nDuur:10-15 min\nAantal: 4 of meer spelers\nVoor iedere speler een bal\nPylonen:\n- 4 om het speelveld af te bakenen.\n- 4 pylonen/hoedjes om de vrije zone aan te\ngeven.\n- 4 pylonen/hoedjes om de startlijn aan te geven.\n- 2 pylonen/hoedjes op de middenlijn aan te\ngeven\nAanwijzingen\n- zorg dat de spelers ook echt starten\nwanneer hun naam genoemd wordt\n- probeer een leuk verhaal van te maken.\nNiet alleen maar ratten en raven roepen."}, {"type": "techniek", "title": "C. TEGENSTANDER VOOR JE: IN EEN RECHTHOEKVORM (ANDERE)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet,\ninzet beweging binnenkant rechter voet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Uitstappen meenemen (Stap 5A)\n- Akka (binnen-buiten) (Stap 3A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nVariatie:\nEen dubbele schaarbeweging door 2x met de voet om de bal heen\nte bewegen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken Uitstappen meenemen\n(Stap 5A) en Akka (binnen-buiten) (Stap 3A).\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening, met het andere\nbeen, in tegenovergestelde richting uit. Daarna\nneemt deze speler de plaats in van speler 2, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VOOR JE: MET KAATSER (2)", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\nDribbelen buitenkant voet:\n- Schaar (Stap 5A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB.Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit.\nC. Daarna speelt hij de bal, voor een kaats, op speler 2 en loopt\ndoor om de bal te ontvangen.\nD. Vervolgens kaatst speler 2 de bal op de doorgelopen speler 1.\nE. Speler 1 controleert/werkt af op doel of werkt direct af op doel.\nF. Speler 2 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nAfstand kaatser vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 neemt de taak over van speler 2\n- Speler 2 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Juist inschatten van de snelheid van de bal\nom met je passen goed uit te komen, zodat\nje direct op doel kunt afwerken.\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Afhankelijk van de situatie met\nde binnenkant of met de volle wreef\n- Standbeen iets voorbij de bal dan blijft de\nbal laag.\n- Standbeen iets achter de bal en raak de bal\naan de onderkant, dan gaat de bal omhoog."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O10', 29, '{"session_a": [{"type": "warming_up", "title": "OVERSTEEK SPEL", "content": "Alle spelers staan met de bal aan de voet aan één kant van het\nveld en één speler staat zonder bal in het midden. Op een teken\nvan de trainer mogen de spelers proberen het veld over te steken.\nDe tikker moet vervolgens proberen de ballen van de spelers\nbuiten het veld te schieten.\nDe spelers van een weggeschoten bal gaan ook in het midden\nstaan om de bal af te pakken.\nVariatie:\n- De spelers moeten zelf hun weggetrapte bal ophalen en weer bij\nde groep aansluiten.\n- Weggeschoten bal ophalen en dan wachten om te zien wie er\nover blijft. De winnaar mag de nieuwe tikker zijn of aanwijzen.\n- Twee of meerdere afpakkers.\nMaterialen\nTijd: 10-15 min\nPylonen:\n4 pylonen om het speelveld uit te zetten.\n2 pylonen/hoedjes om de middenlijn uit te zetten.\nBallen: iedere speler een bal op de tikker na die\nde ballen gaat afpakken.\nAanwijzingen\n- Zorg dat de spelers de bal dicht bij zich\nhouden zodat ze de bal goed kunnen sturen.\n- Laat de spelers telkens op het teken van de\ntrainer starten."}, {"type": "techniek", "title": "STAP 2.1 D: AANBIEDEN, TOT 135º IN Y-VORM", "content": "A. Speler 1 speelt naar speler 2.\n- speler 2 biedt zich \"voorwaarts\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Spelers 3 dribbelt met de bal naar speler 8.\n- speler 3 wisselt van kant ensluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\nIdem aan de andere kant voor de spelers 5 t/m 8, alleen dan met\nlinks uitvoeren.\nVariatie in uitvoering:\n- aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nVariatie in aanbieden:\n- naar rechts\n- naar links\n- achterwaarts\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 4\nAfstand van pylonen:\n1 ste jaars F-pupillen: 5 m\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- wisselen door in de andere rij aan te sluiten.\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "1. (3 : 1 + 2)", "content": "Drie aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdediger de bal kan veroveren.\nWanneer de verdediger de bal onderschept dan moet hij de\nruimte zoeken met een lange pass naar het andere vak om\nzodoende het spel te verleggen.\nTevens gaan 1 verdediger en 1 aanvaller mee naar het andere\nveld. Nu moeten de drie verdedigers d.m.v. samenspel de bal in\nhun bezit zien te houden zonder dat de aanvaller de bal kan\nveroveren. Etc.\nVariatie in aanbieding:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 6\nAfstand tussen de pylonen: 2x (10m bij 8m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- omschakeling van balbezit naar balverlies\n- druk op de bal geven zodat de aanvallers\neen fout maken"}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "STOKKENLOOP (1)", "content": "Is een oefening, waarbij de voorwaartse vormen worden\naangeleerd over de stokken. De oefening is opgebouwd van grove\nmotoriek naar de fijne motoriek. Dat wil zeggen binnen de\nlooptraining, er wordt gewerkt van een skipping naar skipping 45\ngraden en vervolgens naar kort voetenwerk.\nEr moet hierbij wel nadrukkelijk worden gelet op het lichtvoetig\nagreren over de stokken. Dat wil zeggen dat alles met de bal van\nde voet wordt uitgevoerd. Ten allen tijden wordt er op de bal van\nde voet gelopen.\nStap 1: Er wordt met de rechtervoet begonnen. De eerste stok\nwordt voorwaarts genomen en vervolgens wordt er met twee\nvoeten teruggestapt, de andere stokken worden gelopen met één\nvoet tussen de stokken.\nStap 2: Er wordt met de rechtervoet begonnen. De eerste en de\nderde stok worden voorwaarts genomen en vervolgens wordt er\nmet twee voeten teruggestapt, de andere stokken worden\ngelopen met één voet tussen de stokken.\nStap 3: Er wordt met de rechtervoet begonnen. De eerste, de\nderde en de vijfde stok worden voorwaarts genomen en\nvervolgens wordt er met twee voeten teruggestapt, de andere\nstokken worden gelopen met één voet tussen de stokken.\nDifferentiatie:\nLet op!\nDe romphouding moet recht zijn en er moet een duidelijke\narminzet aanwezig zijn.\nMaterialen\nAantal spelers: het gehele team.\nAantal stokkenparcours:\nEén, bij voorkeur twee.\nAantal pylonnen:\n12\nAantal stokken:\n5\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: IN EEN RECHTHOEKVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de voet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan (deze doet alsof hij een speler in de rug heeft).\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Binnen-buitenkant wegdraai (Stap 4)\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\nC. Speler 1 dribbelt naar speler 3\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 3.\n- Speler 1 geeft de bal aan speler 3, etc.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken De Overstap (Stap 5A),\nKappen buitenkant voet (Stap 4A) en Binnen buiten wegdraai\n(Stap 4).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt, na de pass op speler 2, diens\nplaats in. Speler 2 dribbelt naar de plek ter\nhoogte van de overstaande pylonen en geeft\ndaar de bal aan speler 3. Deze speler start de\noefening opnieuw, maar nu in tegengestelde\nrichting, door de bal op de doorgelopen speler 1\nte spelen, etc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "AANVALLEN DOOR MIDDENVELDERS EN AANVALLERS (5 : 4+KEEPER) KLEIN VELD", "content": "D.w.z. dat 5 aanvallers/ middenvelders d.m.v. samenspel kansen\ncreëren.\nDe 4 verdedigers /middenvelders+ keeper kunnen scoren door de\nbal over de lijn van één van de kleine doetjes te dribbelen.\nDe aanvallers kunnen op het grote doel scoren.\nDe oefening start altijd bij de aanvallers.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nMiddenvelders/aanvallers bij aanvallen\ncoachen op:\n- het samenspelen vanuit een halve kom\n- het opkomen van de middenvelder\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (7+11)\n- het loskomen van de tegenstander d.m.v.\nvooracties.\n- het creëren van een twee tegen een situatie.\nMiddenvelders/aanvallers bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)\n- het direct druk zetten op de bal."}, {"type": "partijvorm", "title": "PARTIJVORM 5:5 (2)", "content": "Vijf aanvallers moeten d.m.v. samenspel/ individuele actie 5\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers: 10(15)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 30m bij 25m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-junioren: 5m bij 2m\nDoordraaien:\n- het winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\n- geen score na twee minuten, dan wordt de\nlangst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}]}'::jsonb),
('O10', 30, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER NAAST JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- De verandering (Stap 3)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 D: AANBIEDEN, TOT 135º (ZELFDE/ANDERE BEEN) IN RUITVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de\nlinker/rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechter/linkervoet aan.\nC. Speler 3 speelt naar speler 4\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, aannemen en spelen met het zelfde been.\nVariatie in aanbieden:\n- naar rechts\n- voorwaarts\n- achterwaarts\nVariatie\nVariatie 3: Aanbieden voorwaarts, achterwaarts, rechts en links\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "(4 : 2) OEFENING 3", "content": "Vier aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe verdedigers moeten na het veroveren van de bal op de kleine\ndoeltjes scoren (omschakeling).\nWisselen van taak:De verdediger die het langst in het midden\nheeft gestaan wisselt met de aanvaller die de fout heeft gemaakt\nof hij wisselt met de langst staande aanvaller.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 6\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 12m bij 10m\nKleine doelen: 2x (3m bij 1m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}], "session_b": [{"type": "test", "title": "SPRINTTEST", "content": "Voor deze test wordt in de breedte van het strafschopgebied, op\neen onderlinge afstand van tekens 10 meter, met 5 pylonen een\nparcours uitgezet.\nDe spelers starten de sprint vanaf de zijkant van het “16-\nmetergebied” vanuit stilstand en sprinten vervolgens om de\neerste pylon heen weer terug, gevolgd door een sprint om de\ntweede pylon heen en weer terug. Idem om de derde en de vierde\npylon.\nDe behaalde eindtijd wordt gemeten en vastgelegd.\nMaterialen\nAantal spelers: alle spelers\nAantal pylonen: 5\nAfstand tussen de pylonen: 10 mtr.\n1 stopwatch\nSchrijfbenodigdheden.\n- deze test heeft tot doel om de “reactie/\nacceleratie- en/of de maximale snelheid” te\ntoetsen/meten.\nAanwijzingen\n- zowel heen als terug een zo hoog mogelijke\nsnelheid ontwikkelen\n- kort om de pylon draaien\n- neem minimaal 2-3 minuten rust tussen\ntwee testen."}, {"type": "techniek", "title": "AANBIEDEN, TOT 135º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: alle\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 + 2 KEEPERS", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nD-pupillen: 30m bij 25m\nC-junioren: 35m bij 30m\nB-,A-junioren: 40m bij 35m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O10', 31, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER ACHTER JE: IN LIJNVORM HEEN TERUG", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt naar overstaande pylon.\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Kappen buitenkant voet (Stap 3)\n- Binnen-buitenkant wegdraai (Stap 3)\n- De Overstap (Stap 4)\nC. Speler dribbelt terug en herhaald stap B bij de pylon.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.1 C: INGOOIEN, AANBIEDEN, TOT 90º IN VIERKANT/STROOMVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 gooit de bal in\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 pakt de bal op.\nC. Speler 3 speelt naar speler 4\n- idem als beschreven bij A.\nD. Speler 4 speelt naar speler 5\n- idem als beschreven bij B, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been\n- idem, met rechts aannemen en met links spelen.\nVariatie in aanbieden:\n- Naar rechts\n- Achterwaarts\n- Voorwaarts\nMaterialen\nAantal spelers: 5-7\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nIngooi:\n- beide voeten houden contact met de grond\n- de bal achter het hoofd loslaten\n- beide handen op de bal houden\n- voeten in de richting van het gooien\n- op het juiste been ingooien.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "STAP 2.2 C: DOORKOPPEN VANUIT EEN POSITIE OP DE KNIEËN", "content": "Oefening met 3-tallen, waarbij de aangooiende/ ontvangende\nspelers 1 en 3 een staande positie innemen en speler 2 op de\nknieën zit.\nA. Speler 1 speelt naar speler 2\n- speler 1 gooit de bal onderhands aan.\nB. Speler 2 speelt naar speler 3\n- speler 2 kopt de bal schuin door , etc.\nVariatie in uitvoering:\n- idem in tegengestelde richting, met een aangooi vanaf de\nandere kant.\nMaterialen\nAantal spelers: 3\nAantal ballen: per drietal een bal\nAfstand van pylonen:\n1e jaars E-pupillen: 2 m\n2e jaars E-pupillen: 2 m\nDoordraaien:\n- wisselen van functie naar eigen inzicht\nAanwijzingen\n- bovenlichaam naar achteren, kin op de\nborst .\n- armen voor je houden.\n- juiste moment bovenlichaam naar voren en\narmen naar achter.\n- bal raken met het voorhoofd.\n- de bal goed richting geven, door de\nduwbeweging in de richting van speler 3 te\nmaken.\nLIJNDRIBBEL 3:2 MET DOEL\nMethodiek\nd.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}], "session_b": [{"type": "warming_up", "title": "TENNISBALLENSPEL", "content": "Bij deze oefening wordt het ‘omschakelmoment’ van een speler\naangeleerd en getraind. Door deze oefening wordt een speler\nhandig in het lichtvoetig draaien. Tevens benadrukt deze oefening\nhet ‘laag zitten’ bij het wegdraaien bij de speler.\nOrganisatieuitleg:\nEr zijn bij het spel 4 pylonnen, 4 tennisballen en één hoepel\naanwezig. De pylonnen staan in een plusvorm en op de pylonnen\nliggen de tennisballen.\nSpeluitleg:\nDe speler begint in de hoepel, op een commando van de trainer\nstart de speler naar de eerste pylon. De speler pakt de tennisbal\nmet de rechterhand en geeft de bal over in zijn linkerhand en legt\nhem vervolgens in de hoepel. Vanuit de hoepel vertrekt de zelfde\nspeler naar de tweede pylon en pakt tevens weer een tennisbal\nvan de tweede pylon met zijn rechterhand, geeft deze weer over\nnaar zijn linkerhand en legt vervolgens de tennisbal weer in de\nhoepel. De speler vervolgt de zelfde volgorde ook bij de derde en\nvierde pylon.\nDifferentiatie:\nBiedt de vorm ook aan in een wedstrijdvorm, zodat de oefening\nook op maximale snelheid uitgevoerd moet worden.\nMaterialen\nAantal spelers: het gehele team.\nAantal organisaties:\nZoveel als mogelijk.\nAantal pylonnen voor één organisatie: 4\npylonnen.\nAantal hoepels voor één organisatie:\n1 hoepel\nOrganisatie:\nPer situatie voert één speler de oefening uit.\nAanwijzingen\nLet op!\nZorg ervoor dat de oefening volledig wordt\nuitgevoerd. Dat de speler tevens bij elke\nomschakeling ‘laag zit’ (gebogen knieën\nheeft)."}, {"type": "techniek", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN EEN RECHTHOEKVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Kappen buitenkant voet (Stap 4A)\n- Pirouette (Stap 6A)\n- Aai achter standbeen (Stap 5A)\n- De Schijntrap (Stap 5A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan en voert nu, met het andere been, in tegengestelde richting\ndezelfde oefening uit.\n- Speler 2 geeft de bal aan speler 3, etc.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 5: Het oefenen van de technieken Aai kappen achter\nstandbeen (Stap 5A), Kappen buitenkant voet (Stap 4A), Pirouette\n(Stap 6A) en De schijntrap (Stap 5A).\nMaterialen\nAantal spelers: 3-5\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 passed de bal op speler 2. Deze speler\nvoert de oefening in de tegenovergestelde\nrichting met het andere been uit en passed de\nbal op speler 3. Enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER VANAF DE ZIJKANT: MET KAATSER", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- Kappen buitenkant voet (Stap 4A)\n- Pirouette (Stap 6A)\n- Aai-kappen achter het standbeen (Stap 5A)\n- Schijntrap (Stap 5A)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB. Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit.\nC. Daarna speelt hij de bal, voor een kaats, op speler 2 en loopt\ndoor om de bal te ontvangen.\nD. Vervolgens kaatst speler 2 kaats de bal op de doorgelopen\nspeler 1.\nE. Speler 1 controleert/werkt af op doel of werkt direct af op doel.\nF. Speler 2 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nAfstand kaatser vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 neemt de taak over van speler 2\n- Speler 2 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Juist inschatten van de snelheid van de bal\nom met je passen goed uit te komen, zodat\nje direct op doel kunt afwerken.\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Afhankelijk van de situatie met\nde binnenkant of met de volle wreef\n- Standbeen iets voorbij de bal dan blijft de\nbal laag.\n- Standbeen iets achter de bal en raak de bal\naan de onderkant, dan gaat de bal omhoog."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O10', 32, '{"session_a": [{"type": "warming_up", "title": "OVERSTEEK SPEL", "content": "Alle spelers staan met de bal aan de voet aan één kant van het\nveld en één speler staat zonder bal in het midden. Op een teken\nvan de trainer mogen de spelers proberen het veld over te steken.\nDe tikker moet vervolgens proberen de ballen van de spelers\nbuiten het veld te schieten.\nDe spelers van een weggeschoten bal gaan ook in het midden\nstaan om de bal af te pakken.\nVariatie:\n- De spelers moeten zelf hun weggetrapte bal ophalen en weer bij\nde groep aansluiten.\n- Weggeschoten bal ophalen en dan wachten om te zien wie er\nover blijft. De winnaar mag de nieuwe tikker zijn of aanwijzen.\n- Twee of meerdere afpakkers.\nMaterialen\nTijd: 10-15 min\nPylonen:\n4 pylonen om het speelveld uit te zetten.\n2 pylonen/hoedjes om de middenlijn uit te zetten.\nBallen: iedere speler een bal op de tikker na die\nde ballen gaat afpakken.\nAanwijzingen\n- Zorg dat de spelers de bal dicht bij zich\nhouden zodat ze de bal goed kunnen sturen.\n- Laat de spelers telkens op het teken van de\ntrainer starten."}, {"type": "techniek", "title": "STAP 2.1 E: AANBIEDEN, TOT 180º MET HET ZELFDE/ANDERE BEEN IN LIJNVORM", "content": "A. Speler 1 speelt de bal naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nlinker/rechtervoet aan.\nB. Speler 2 speelt de bal naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de\nrechter/linkervoet\n- speler 3 neemt de bal met de binnenkant van de\nlinker/rechtervoet aan, etc.\nVariatie in uitvoering:\n- idem, aannemen en spelen met het zelfde been.\nVariatie in aanbieden:\n- naar rechts\n- naar links\n- achterwaarts\nVariatie\nVariatie 3: Aanbieden voorwaarts, achterwaarts, rechts en links\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nAfstand van pylonen:\n2e jaars F-pupillen: 8 m\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- wisselen naar eigen inzicht\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelend\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "AANBIEDEN, TOT 180º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: alle\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 2:2 (2)", "content": "Twee aanvallers proberen, d.m.v. samenspel/ individuele actie, 2\nverdedigers uit te spelen en daarna in het tegenoverstaande doel\nte scoren.\nDe verdedigers kunnen ook, nadat zij de bal hebben afgepakt, in\nhet andere doel scoren.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 2 man en 1 keeper.\nHet scorende team behoudt balbezit en start vanaf hun doelman.\nHet 3e team zorgt voor aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:4(6)+2(3) keepers\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren naar de zijkant van het veld\nvan de aanvaller in balbezit\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht\nvoor:genoeg ballen om het veld, een strakke\nfelle coaching."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "STOKKENLOOP TIKKERTJE", "content": "Bij deze oefening staan de spelers verdeeld in 2 groepen van elk 6 spelers\ntegenover elkaar aan beide zijden van het “stokken-parcours”.\nAan het eind van beide parcoursen staan twee verschillend gekleurde pylonen\nmet aan weerszijden op 10 meter afstand daarvan nog een pylon.\nEr wordt tegelijkertijd gestart met het stokkenparcours(foutloos lopen, anders\nopnieuw).\nDe eerste aangekomene tikt een pylon aan en kiest vervolgens een richting.\nDe laatst aangekomene moet nadat hij de pylon heeft aangetikt de ander\nproberen in te halen en te tikken.\nLet op!\nBij beheersing van het stokkenparcours kan er op snelheid wordt gewerkt.\nMaterialen\nAantal spelers: 12\nAantal pylonen: 24\nOrganisatie:\nDe spelers staan tegenover elkaar met een ruimte er tussen van 20 á 25 meter.\nDe onderlinge afstanden van het stokkenparcours moet even groot zijn."}, {"type": "techniek", "title": "B. TEGENSTANDER NAAST JE: IN EEN RECHTHOEKVORM", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 dribbelt richting middelste pylonen\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 maakt de beweging\n- Kappen achter standbeen (Stap 3A)\n- Kappen binnenkant voet (Stap 4A)\n- Kappen buitenkant voet (Stap 4A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nLet op! Bij een inzet met de linkervoet over de bal, moet men ook\nmet links dribbelen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Kappen binnenkant\nvoet (Stap 4A), Kappen buitenkant voet (Stap 4A) en Kappen\nachter standbeen (Stap 3A).\nMaterialen\nAantal spelers: 3-5\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening in\ntegenovergestelde richting uit en passed de bal\nop zijn beurt weer op speler 3, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "OPBOUW DOOR VERDEDIGERS EN MIDDENVELDER (5+KEEPER : 4) KLEIN VELD", "content": "D.w.z. dat 5 verdedigers / middenvelders + keeper d.m.v.\nsamenspel 4 aanvallers/ middenvelders uitspelen, om daarna te\nscoren door de bal over de lijn van een van de doeltjes te\ndribbelen.\nDe aanvallers kunnen de afgepakte bal scoren op het grote doel.\nDe opbouw start altijd bij de doelman.\nMaterialen\nAantal spelers: 9+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 25m bij 30m\nD-pupillen: 30m bij 35m\nC-,B-,A-junioren: 35m bij 40m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nSpelers te kort! Zorg dan dat je opbouwende\npartij een speler meer heeft.\nAanwijzingen\nVerdedigers/middenvelders bij opbouw\ncoachen op:\n- het breed maken van het veld door de\nverdedigers. Wordt één van de verdedigers\nin gespeeld dan knijpt de ander naar binnen\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (2+5)\n- het diep weglopen, om ruimte te maken,\nvan de centrale middenvelder\n- het benutten van een overtalsituatie\nVerdedigers/middenvelders bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}, {"type": "partijvorm", "title": "PARTIJVORM 5:5 (2)", "content": "Vijf aanvallers moeten d.m.v. samenspel/ individuele actie 5\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers: 10(15)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 30m bij 25m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-junioren: 5m bij 2m\nDoordraaien:\n- het winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\n- geen score na twee minuten, dan wordt de\nlangst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}]}'::jsonb)
